/// Structural carrier used by every map-key adapter.
#[derive(Clone, Debug)]
pub enum JetMapKey {
    Int(i64),
    UInt(u64),
    String(String),
    Bool(bool),
    Char(char),
    Record(Vec<JetMapKey>),
}

/// The one codegen Prelude seam for recursively encoding key-eligible values.
pub trait JetMapKeyEncode {
    fn jet_map_key(&self) -> JetMapKey;
}

impl JetMapKeyEncode for i8 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::Int(*self as i64)
    }
}

impl JetMapKeyEncode for i16 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::Int(*self as i64)
    }
}

impl JetMapKeyEncode for i32 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::Int(*self as i64)
    }
}

impl JetMapKeyEncode for i64 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::Int(*self)
    }
}

impl JetMapKeyEncode for u8 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::UInt(*self as u64)
    }
}

impl JetMapKeyEncode for u16 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::UInt(*self as u64)
    }
}

impl JetMapKeyEncode for u32 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::UInt(*self as u64)
    }
}

impl JetMapKeyEncode for u64 {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::UInt(*self)
    }
}

impl JetMapKeyEncode for String {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::String(self.clone())
    }
}

impl JetMapKeyEncode for bool {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::Bool(*self)
    }
}

impl JetMapKeyEncode for char {
    fn jet_map_key(&self) -> JetMapKey {
        JetMapKey::Char(*self)
    }
}

fn jet_map_key_kind(key: &JetMapKey) -> u8 {
    match key {
        JetMapKey::Int(_) => 0,
        JetMapKey::UInt(_) => 1,
        JetMapKey::String(_) => 2,
        JetMapKey::Bool(_) => 3,
        JetMapKey::Char(_) => 4,
        JetMapKey::Record(_) => 5,
    }
}

/// The single deep value-semantic comparison used by map-key adapters.
pub fn jet_map_key_cmp(left: &JetMapKey, right: &JetMapKey) -> std::cmp::Ordering {
    match (left, right) {
        (JetMapKey::Int(left), JetMapKey::Int(right)) => left.cmp(right),
        (JetMapKey::UInt(left), JetMapKey::UInt(right)) => left.cmp(right),
        (JetMapKey::String(left), JetMapKey::String(right)) => left.cmp(right),
        (JetMapKey::Bool(left), JetMapKey::Bool(right)) => left.cmp(right),
        (JetMapKey::Char(left), JetMapKey::Char(right)) => left.cmp(right),
        (JetMapKey::Record(left), JetMapKey::Record(right)) => {
            for (left, right) in left.iter().zip(right) {
                let ordering = jet_map_key_cmp(left, right);
                if ordering != std::cmp::Ordering::Equal {
                    return ordering;
                }
            }
            left.len().cmp(&right.len())
        }
        _ => jet_map_key_kind(left).cmp(&jet_map_key_kind(right)),
    }
}

impl PartialEq for JetMapKey {
    fn eq(&self, other: &Self) -> bool {
        jet_map_key_cmp(self, other) == std::cmp::Ordering::Equal
    }
}

impl Eq for JetMapKey {}

impl PartialOrd for JetMapKey {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(jet_map_key_cmp(self, other))
    }
}

impl Ord for JetMapKey {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        jet_map_key_cmp(self, other)
    }
}
// D-FAIL-BREACH1=A: the runtime call-depth counter is task-local.
//
// A resident engine may run several Jet tasks against one runtime value. The
// source call stack belongs to the task, not to that shared runtime. AOT uses
// this same kernel through `Prelude/Core.rs`; the JIT adapter only marshals
// entry and leave calls into it.
thread_local! {
    static JET_RUNTIME_STACK_DEPTH: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

pub fn jet_runtime_stack_enter() -> bool {
    JET_RUNTIME_STACK_DEPTH.with(|depth| {
        let next = depth.get().saturating_add(1);
        depth.set(next);
        next > JET_RUNTIME_STACK_LIMIT
    })
}

pub fn jet_runtime_stack_leave() {
    JET_RUNTIME_STACK_DEPTH.with(|depth| depth.set(depth.get().saturating_sub(1)));
}
/// D-AUTHORITY-WORD2=E: the one named Abilities value that crosses boundaries.
/// Abilities remains ordinary data; every engine calls
/// the helpers below instead of keeping a second policy implementation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JetAuthority {
    rights: std::collections::BTreeSet<String>,
}

impl JetAuthority {
    /// Build the one runtime carrier for a checked named `#Abilities` scope.
    /// The caller has already resolved the names; this method only stores the
    /// rights set, so every execution tier shares the same relation.
    pub fn from_rights(rights: Vec<String>) -> Self {
        Self {
            rights: jet_authority_rights_from_strings(rights),
        }
    }

    /// Generated TIR uses the prefixed constructor name to keep the runtime
    /// helper distinct from a user-defined static method. Both spellings use
    /// this one authority constructor.
    pub fn __jet_from_rights(rights: Vec<String>) -> Self {
        Self::from_rights(rights)
    }

    /// D-AUTHORITY-NAME1=A / D-AGENT-EXEC1: the workspace value names the
    /// default resource boundary explicitly. The executor treats omitted
    /// resources as denied; these entries are the only default grants.
    pub fn workspace() -> Self {
        Self {
            rights: jet_authority_workspace_rights(),
        }
    }
}

pub(crate) fn jet_authority_rights_from_strings(
    rights: Vec<String>,
) -> std::collections::BTreeSet<String> {
    rights.into_iter().collect()
}

/// Marshal the ordinary Authority carrier across the sandboxed plugin bridge.
/// The plugin runtime stores this wire value; it never turns it into host
/// imports or a second permission policy.
pub(crate) fn jet_authority_to_wire(authority: &JetAuthority) -> String {
    authority.rights.iter().cloned().collect::<Vec<_>>().join("\n")
}

fn jet_authority_covers(held: &str, requested: &str) -> bool {
    held == requested
        || requested
            .strip_prefix(held)
            .is_some_and(|tail| tail.starts_with('.') || tail.starts_with(':') || tail.starts_with('/'))
}

/// D-AGENT-EXEC1: the default workspace process scope is a repository read
/// plus a private build write. Network, home, secrets, devices, inherited
/// handles, and every other resource stay absent and therefore denied.
pub(crate) fn jet_authority_workspace_rights() -> std::collections::BTreeSet<String> {
    [
        "FS.Read:repo".to_string(),
        "FS.Write:.jet/build".to_string(),
    ]
    .into_iter()
    .collect()
}

/// D-AUTHORITY-NAME1=A: `with` can only attenuate a right already held.
pub(crate) fn jet_authority_with_right(
    held: &std::collections::BTreeSet<String>,
    requested: &str,
) -> Result<std::collections::BTreeSet<String>, String> {
    if held.iter().any(|bound| jet_authority_covers(bound, requested)) {
        Ok([requested.to_string()].into_iter().collect())
    } else {
        Err(format!(
            "E0712: abilities cannot narrow to `{requested}` outside its held rights"
        ))
    }
}

/// D-AUTHORITY-NAME1=A: `without` removes a right subtree and never widens.
pub(crate) fn jet_authority_without_right(
    held: &std::collections::BTreeSet<String>,
    requested: &str,
) -> std::collections::BTreeSet<String> {
    held.iter()
        .filter(|held_right| !jet_authority_covers(requested, held_right))
        .cloned()
        .collect()
}

/// Shared AOT/Wasm operation for the `with` family member.
pub(crate) fn jet_authority_with(
    authority: &JetAuthority,
    requested: &str,
) -> Result<JetAuthority, String> {
    jet_authority_with_right(&authority.rights, requested)
        .map(|rights| JetAuthority { rights })
}

/// Shared AOT/Wasm operation for the `without` family member.
pub(crate) fn jet_authority_without(
    authority: &JetAuthority,
    requested: &str,
) -> JetAuthority {
    JetAuthority {
        rights: jet_authority_without_right(&authority.rights, requested),
    }
}

/// D-PERSIST-DEVSTATE1=A: AOT's persistent slot is an interior-mutable
/// Prelude cell. The generated module binding stays safe Rust; the execution
/// engine only reads and writes this one storage abstraction.
pub struct JetPersistCell<T> {
    value: std::sync::Mutex<T>,
}

impl<T> JetPersistCell<T> {
    pub const fn new(value: T) -> Self {
        Self {
            value: std::sync::Mutex::new(value),
        }
    }

    fn guard(&self) -> std::sync::MutexGuard<'_, T> {
        self.value
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    pub fn get(&self) -> T
    where
        T: Clone,
    {
        self.guard().clone()
    }

    pub fn set(&self, value: T) {
        *self.guard() = value;
    }
}

