fn jet_fixed_list_concat<
    T: Clone,
    const LEFT: usize,
    const RIGHT: usize,
    const TOTAL: usize,
>(
    left: &[T; LEFT],
    right: &[T; RIGHT],
) -> [T; TOTAL] {
    debug_assert_eq!(TOTAL, LEFT + RIGHT);
    std::array::from_fn(|index| {
        if index < LEFT {
            left[index].clone()
        } else {
            right[index - LEFT].clone()
        }
    })
}

