fn jet_ordering_then(first: &__jet_Ordering, second: &__jet_Ordering) -> __jet_Ordering {
    match first {
        __jet_Ordering::__jet_Equal => *second,
        _ => *first,
    }
}

fn jet_ordering_reverse(value: &__jet_Ordering) -> __jet_Ordering {
    match value {
        __jet_Ordering::__jet_Less => __jet_Ordering::__jet_Greater,
        __jet_Ordering::__jet_Greater => __jet_Ordering::__jet_Less,
        __jet_Ordering::__jet_Equal => __jet_Ordering::__jet_Equal,
    }
}
// I9: one checked element-access policy for every borrowed
// view. Tensor-specific window addressing remains in Compute.rs; this part
// owns the final logical index and get/set operation for both AOT and ambient.

fn jet_view_address(len: usize, index: i64) -> Result<usize, String> {
    let len = i64::try_from(len).unwrap_or(i64::MAX);
    if index < 0 || index >= len {
        return Err(jet_list_bounds_message(len, index));
    }
    Ok(index as usize)
}

fn jet_view_get_checked<T: Clone>(view: &[T], index: i64) -> Result<T, String> {
    let index = jet_view_address(view.len(), index)?;
    view.get(index)
        .cloned()
        .ok_or_else(|| "view index is outside storage".to_string())
}

fn jet_view_set_checked<T>(view: &mut [T], index: i64, value: T) -> Result<(), String> {
    let index = jet_view_address(view.len(), index)?;
    let Some(slot) = view.get_mut(index) else {
        return Err("view index is outside storage".to_string());
    };
    *slot = value;
    Ok(())
}

fn jet_view_set_f64_checked(view: &mut [f64], index: i64, value: f64) -> Result<(), String> {
    if !value.is_finite() {
        return Err("Tensor values must be finite".to_string());
    }
    jet_view_set_checked(view, index, value)
}

fn jet_view_get<T: Clone>(view: &[T], index: i64, file: &str, line: u32) -> T {
    match jet_view_get_checked(view, index) {
        Ok(value) => value,
        Err(error) => jet_panic(file, line, &error),
    }
}

fn jet_view_set<T>(view: &mut [T], index: i64, value: T, file: &str, line: u32) {
    if let Err(error) = jet_view_set_checked(view, index, value) {
        jet_panic(file, line, &error);
    }
}

fn jet_view_set_f64(view: &mut [f64], index: i64, value: f64, file: &str, line: u32) {
    if let Err(error) = jet_view_set_f64_checked(view, index, value) {
        jet_panic(file, line, &error);
    }
}

/// One shared setter seam for borrowed float storage and Tensor storage.
/// Compute.rs supplies the Tensor implementation; this always-present part
/// supplies the ordinary float-view implementation so the symbol remains
/// available even when a program does not import core.compute.
trait JetComputeSetTarget {
    type Error;

    fn jet_compute_set_target(
        &mut self,
        indices: &[i64],
        value: f64,
    ) -> Result<(), Self::Error>;
}

impl JetComputeSetTarget for [f64] {
    type Error = String;

    fn jet_compute_set_target(
        &mut self,
        indices: &[i64],
        value: f64,
    ) -> Result<(), Self::Error> {
        let [index] = indices else {
            return Err("a float view set expects one index".to_string());
        };
        jet_view_set_f64_checked(self, *index, value)
    }
}

fn jet_compute_set<T: JetComputeSetTarget + ?Sized>(
    target: &mut T,
    indices: &[i64],
    value: f64,
) -> Result<(), T::Error> {
    target.jet_compute_set_target(indices, value)
}
// D-EXPOP1=A / D-EXPSEM1=A: the one power surface for `^` and `^=`.
//
// Every tier that runs generated Rust — the native build and the wasm module —
// includes this same file, so a power means the same thing everywhere. The
// the Prelude's shared arithmetic stop carries the report code and wording.
//
// `^` on whole numbers is exact. A result outside the type's range traps the
// way a multiplication does. A written negative exponent is lowered to the
// exact Fraction carrier before this helper; a dynamic negative exponent has
// no whole-number answer and traps. `^` on floats is the ordinary
// floating-point power.
//
// The exponent arrives as an `i128` so an exponent of any integer width,
// signed or unsigned, reaches here losslessly.
const JET_POW_NEGATIVE: &str = JET_ARITHMETIC_POWER_NEGATIVE;
const JET_POW_OVERFLOW: &str = JET_ARITHMETIC_POWER_OVERFLOW;

trait JetPow: Copy {
    fn jet_pow(self, exponent: i128, file: &str, line: u32) -> Self;
}
macro_rules! jet_pow_impl {
    ($($t:ty),*) => { $(
        impl JetPow for $t {
            fn jet_pow(self, exponent: i128, file: &str, line: u32) -> Self {
                if exponent < 0 {
                    jet_arithmetic_stop(file, line, JET_POW_NEGATIVE);
                }
                if exponent > u32::MAX as i128 {
                    jet_arithmetic_stop(file, line, JET_POW_OVERFLOW);
                }
                self.checked_pow(exponent as u32)
                    .unwrap_or_else(|| jet_arithmetic_stop(file, line, JET_POW_OVERFLOW))
            }
        }
    )* };
}
jet_pow_impl!(i8, i16, i32, i64, u8, u16, u32, u64);

trait JetPowFloat: Copy {
    fn jet_pow(self, exponent: Self) -> Self;
}
impl JetPowFloat for f64 {
    fn jet_pow(self, exponent: f64) -> f64 {
        self.powf(exponent)
    }
}
impl JetPowFloat for f32 {
    fn jet_pow(self, exponent: f32) -> f32 {
        self.powf(exponent)
    }
}
// D-FLOORDIV1=A: the one floor-division surface for `/%` and `/%=`.
//
// Every tier that runs generated Rust — the native build and the wasm module —
// includes this same file, so `/%` means the same thing everywhere. The
// Prelude's shared arithmetic stop carries the report code and wording.
//
// `/%` rounds the answer down, toward negative infinity: `7 /% 2` is 3 and
// `-7 /% 2` is -4. Rust's `/` rounds toward zero instead, so a signed answer
// that came out one too high is corrected here. Dividing by zero traps, the
// same as `/` does. On floats `/%` is the ordinary division with the answer
// rounded down.
const JET_FLOORDIV_ZERO: &str = JET_ARITHMETIC_DIVIDE_ZERO;
const JET_FLOORDIV_OVERFLOW: &str = JET_ARITHMETIC_DIVIDE_OVERFLOW;

// Fixed-width `/` uses one policy for signed and unsigned values. The caller
// supplies the result range because the evaluator carries every IntN value in
// an i64, while AOT calls this with the concrete Rust width.
const JET_DIVISION_ERROR: &str = JET_ARITHMETIC_DIVISION_ERROR;

pub fn jet_division(
    left: i128,
    right: i128,
    minimum: i128,
    maximum: i128,
) -> Result<i128, &'static str> {
    let quotient = left.checked_div(right).ok_or(JET_DIVISION_ERROR)?;
    if (minimum..=maximum).contains(&quotient) {
        Ok(quotient)
    } else {
        Err(JET_DIVISION_ERROR)
    }
}

trait JetFloorDiv: Copy {
    fn jet_floordiv(self, rhs: Self, file: &str, line: u32) -> Self;
}
// Signed: the answer rounds toward zero, so subtract one whenever a non-zero
// remainder means the true answer sat below it.
macro_rules! jet_floordiv_signed {
    ($($t:ty),*) => { $(
        impl JetFloorDiv for $t {
            fn jet_floordiv(self, rhs: Self, file: &str, line: u32) -> Self {
                if rhs == 0 {
                    jet_arithmetic_stop(file, line, JET_FLOORDIV_ZERO);
                }
                let quotient = match self.checked_div(rhs) {
                    Some(quotient) => quotient,
                    None => jet_arithmetic_stop(file, line, JET_FLOORDIV_OVERFLOW),
                };
                let remainder = self.wrapping_rem(rhs);
                if remainder != 0 && (remainder < 0) != (rhs < 0) {
                    quotient - 1
                } else {
                    quotient
                }
            }
        }
    )* };
}
// Unsigned: nothing is ever below zero, so rounding down is plain division.
macro_rules! jet_floordiv_unsigned {
    ($($t:ty),*) => { $(
        impl JetFloorDiv for $t {
            fn jet_floordiv(self, rhs: Self, file: &str, line: u32) -> Self {
                if rhs == 0 {
                    jet_arithmetic_stop(file, line, JET_FLOORDIV_ZERO);
                }
                self / rhs
            }
        }
    )* };
}
jet_floordiv_signed!(i8, i16, i32, i64);
jet_floordiv_unsigned!(u8, u16, u32, u64);

// D-MODSEM1=A: `%` is the floored modulo, the partner of `/%`. Its answer
// takes the divisor's sign, so `-7 % 2` is 1, and for every pair of whole
// numbers `a == b * (a /% b) + a % b`. Rust's `%` is the truncated remainder,
// which Jet spells `%%`, so the floored one is built here.
trait JetModulo: Copy {
    fn jet_mod(self, rhs: Self, file: &str, line: u32) -> Self;
}
// Signed: the remainder comes back with the dividend's sign, so add the
// divisor whenever the two signs disagree.
macro_rules! jet_mod_signed {
    ($($t:ty),*) => { $(
        impl JetModulo for $t {
            fn jet_mod(self, rhs: Self, file: &str, line: u32) -> Self {
                if rhs == 0 {
                    jet_arithmetic_stop(file, line, JET_FLOORDIV_ZERO);
                }
                // `MIN % -1` is 0 and fits, so it must answer rather than trap —
                // `%%` answers 0 there too, and D-MODSEM1 says the two agree
                // whenever they can.
                let remainder = self.wrapping_rem(rhs);
                if remainder != 0 && (remainder < 0) != (rhs < 0) {
                    remainder.wrapping_add(rhs)
                } else {
                    remainder
                }
            }
        }
    )* };
}
// Unsigned: nothing is ever below zero, so the two remainders agree.
macro_rules! jet_mod_unsigned {
    ($($t:ty),*) => { $(
        impl JetModulo for $t {
            fn jet_mod(self, rhs: Self, file: &str, line: u32) -> Self {
                if rhs == 0 {
                    jet_arithmetic_stop(file, line, JET_FLOORDIV_ZERO);
                }
                self % rhs
            }
        }
    )* };
}
jet_mod_signed!(i8, i16, i32, i64);
jet_mod_unsigned!(u8, u16, u32, u64);

// D-MODSEM1=A: `%%` is the truncated remainder, the partner of `/`. Rust's `%`
// already truncates, so this only adds the traps: a zero divisor, and the one
// signed pair whose remainder overflows.
trait JetTruncRem: Copy {
    fn jet_trunc_rem(self, rhs: Self, file: &str, line: u32) -> Self;
}
macro_rules! jet_trunc_rem_impl {
    ($($t:ty),*) => { $(
        impl JetTruncRem for $t {
            fn jet_trunc_rem(self, rhs: Self, file: &str, line: u32) -> Self {
                if rhs == 0 {
                    jet_arithmetic_stop(file, line, JET_FLOORDIV_ZERO);
                }
                // `MIN %% -1` is 0 and fits, so it answers rather than trapping —
                // the same value `%` gives, which is what D-MODSEM1 asks for.
                self.wrapping_rem(rhs)
            }
        }
    )* };
}
jet_trunc_rem_impl!(i8, i16, i32, i64, u8, u16, u32, u64);

trait JetFloorDivFloat: Copy {
    fn jet_floordiv(self, rhs: Self) -> Self;
}
impl JetFloorDivFloat for f64 {
    fn jet_floordiv(self, rhs: f64) -> f64 {
        (self / rhs).floor()
    }
}
impl JetFloorDivFloat for f32 {
    fn jet_floordiv(self, rhs: f32) -> f32 {
        (self / rhs).floor()
    }
}
// D-TYPEDTEXT1=D: one typed-text semantic core for AOT and TIR adapters.

pub fn jet_typed_sql_raw(template: String) -> (String, Vec<String>) {
    (template, Vec::new())
}

pub fn jet_typed_sql_interpolate(literals: &[&str], holes: Vec<String>) -> (String, Vec<String>) {
    let mut template = String::new();
    for (index, literal) in literals.iter().enumerate() {
        template.push_str(literal);
        if index < holes.len() {
            template.push('?');
        }
    }
    (template, holes)
}

pub fn jet_typed_sql_template(value: &(String, Vec<String>)) -> String {
    value.0.clone()
}

pub fn jet_typed_sql_params(value: &(String, Vec<String>)) -> Vec<String> {
    value.1.clone()
}

pub fn jet_typed_html_raw(value: String) -> String {
    value
}

pub fn jet_typed_html_text(value: String) -> String {
    value
}

pub fn jet_typed_html_escape(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(ch),
        }
    }
    out
}

pub fn jet_typed_html_interpolate(literals: &[&str], holes: Vec<String>) -> String {
    let mut out = String::new();
    for (index, literal) in literals.iter().enumerate() {
        out.push_str(literal);
        if let Some(hole) = holes.get(index) {
            out.push_str(&jet_typed_html_escape(hole));
        }
    }
    out
}

pub fn jet_typed_sh_raw(value: String) -> Vec<String> {
    value.split_whitespace().map(str::to_string).collect()
}

pub fn jet_typed_sh_interpolate(literals: &[&str], holes: Vec<String>) -> Vec<String> {
    let mut argv = Vec::new();
    for (index, literal) in literals.iter().enumerate() {
        argv.extend(literal.split_whitespace().map(str::to_string));
        if let Some(hole) = holes.get(index) {
            argv.push(hole.clone());
        }
    }
    argv
}

// D-BOUND-HEAD1=A: checked boundary heads use this same interpolation kernel
// in AOT, JIT, interpreter, and comptime adapters. The adapters marshal lists
// and nominal values; they do not decide encoding or traversal policy.

pub fn jet_typed_path_interpolate(literals: &[&str], holes: &[String]) -> String {
    interpolate_typed_head(literals, holes, encode_path_component)
}

pub fn jet_typed_datetime_interpolate(literals: &[&str], holes: &[String]) -> String {
    interpolate_typed_head(literals, holes, |hole| hole.to_string())
}

pub fn jet_validate_typed_path_literal(literals: &[&str]) -> Result<(), String> {
    if literals.iter().any(|literal| literal.contains('\0')) {
        Err("a Path cannot contain a NUL character".to_string())
    } else {
        Ok(())
    }
}

fn interpolate_typed_head(
    literals: &[&str],
    holes: &[String],
    encode_hole: impl Fn(&str) -> String,
) -> String {
    let mut out = String::new();
    for (index, literal) in literals.iter().enumerate() {
        out.push_str(literal);
        if let Some(hole) = holes.get(index) {
            out.push_str(&encode_hole(hole));
        }
    }
    out
}

fn encode_path_component(value: &str) -> String {
    // Separators and control bytes are encoded, so a hole contributes one
    // filesystem component. Encode the two traversal spellings as well;
    // `..` must never become a parent component after interpolation.
    if matches!(value, "." | "..") {
        return value
            .as_bytes()
            .iter()
            .map(|byte| format!("%{byte:02X}"))
            .collect();
    }
    percent_encode_path(value)
}

fn percent_encode_path(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for &byte in value.as_bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            out.push(char::from(byte));
        } else {
            out.push('%');
            out.push(hex_digit(byte >> 4));
            out.push(hex_digit(byte & 0x0f));
        }
    }
    out
}

fn hex_digit(nibble: u8) -> char {
    match nibble {
        0..=9 => char::from(b'0' + nibble),
        10..=15 => char::from(b'A' + nibble - 10),
        _ => unreachable!("percent hex nibble is always four bits"),
    }
}

#[cfg(test)]
mod typed_boundary_tests {
    use super::*;

    #[test]
    fn path_holes_are_one_component() {
        assert_eq!(
            jet_typed_path_interpolate(
                &["/data/", ".json"],
                &["ada/../etc".to_string()],
            ),
            "/data/ada%2F..%2Fetc.json"
        );
        assert_eq!(
            jet_typed_path_interpolate(&["/data/", ""], &["..".to_string()]),
            "/data/%2E%2E"
        );
    }

    #[test]
    fn path_literal_validation_rejects_nul() {
        assert!(jet_validate_typed_path_literal(&["/data/log"]).is_ok());
        assert!(jet_validate_typed_path_literal(&["/data/\0log"]).is_err());
    }
}
#[allow(dead_code)]
pub fn jet_progress_render(
    description: &str,
    format: &str,
    count: usize,
    total: Option<usize>,
    elapsed: f64,
    no_color: bool,
) -> String {
    let total_text = total.map_or_else(|| "?".to_string(), |n| n.to_string());
    let percent = total
        .filter(|n| *n > 0)
        .map(|n| (((count.min(n) as u128) * 100) / (n as u128)).to_string())
        .unwrap_or_else(|| if total == Some(0) { "100".to_string() } else { "?".to_string() });
    let remaining = match total {
        Some(n) if count >= n => "0.00s".to_string(),
        Some(n) if count > 0 => {
            let seconds = elapsed * (n - count) as f64 / count as f64;
            format!("{seconds:.2}s")
        }
        Some(_) | None => "?".to_string(),
    };
    let rate = if elapsed > 0.0 {
        format!("{:.2}/s", count as f64 / elapsed)
    } else {
        "?/s".to_string()
    };
    let template = if format.is_empty() {
        "{description} {percent}% {count}/{total} elapsed {elapsed} remaining {remaining} rate {rate}"
    } else {
        format
    };
    let mut rendered = template.to_string();
    for (key, value) in [
        ("description", description),
        ("percent", percent.as_str()),
        ("count", &count.to_string()),
        ("total", total_text.as_str()),
        ("elapsed", &format!("{elapsed:.2}s")),
        ("remaining", remaining.as_str()),
        ("rate", rate.as_str()),
    ] {
        rendered = rendered.replace(&format!("{{{key}}}"), value);
    }
    if no_color {
        jet_progress_strip_ansi(&rendered)
    } else {
        rendered
    }
}

#[allow(dead_code)]
fn jet_progress_strip_ansi(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut escape = false;
    for ch in text.chars() {
        if escape {
            if ch.is_ascii_alphabetic() {
                escape = false;
            }
        } else if ch == '\x1b' {
            escape = true;
        } else {
            out.push(ch);
        }
    }
    out
}

#[cfg(test)]
mod progress_render_tests {
    use super::jet_progress_render;

    #[test]
    fn renders_all_fields_and_zero_remaining_at_completion() {
        let rendered = jet_progress_render(
            "work",
            "{description}|{percent}|{count}|{total}|{elapsed}|{remaining}|{rate}",
            4,
            Some(4),
            2.0,
            false,
        );
        assert_eq!(rendered, "work|100|4|4|2.00s|0.00s|2.00/s");
    }

    #[test]
    fn no_color_removes_ansi_sequences() {
        let rendered = jet_progress_render("work", "\x1b[32m{description}\x1b[0m", 1, Some(2), 1.0, true);
        assert_eq!(rendered, "work");
    }

    #[test]
    fn default_format_exposes_runtime_metrics() {
        let rendered = jet_progress_render("work", "", 2, Some(4), 2.0, false);
        assert!(rendered.contains("elapsed 2.00s"));
        assert!(rendered.contains("remaining 2.00s"));
        assert!(rendered.contains("rate 1.00/s"));
    }

    #[test]
    fn unknown_total_is_rendered_without_fake_percent_or_remaining() {
        let rendered = jet_progress_render(
            "work",
            "{description}|{percent}|{count}|{total}|{remaining}",
            2,
            None,
            1.0,
            false,
        );
        assert_eq!(rendered, "work|?|2|?|?");
    }
}
/// Growable byte builder with one read cursor. EOF is `position == len`
/// (D-ITERTOOLS1=A / #1467). String-like ops decode UTF-8 then reuse String
/// behavior; invalid UTF-8 uses lossy replacement so beginners are not blocked.
#[derive(Clone)]
pub(crate) struct JetByteBuffer {
    pub(crate) bytes: Vec<u8>,
    pub(crate) pos: usize,
}
impl JetByteBuffer {
    pub(crate) fn new() -> Self {
        Self {
            bytes: Vec::new(),
            pos: 0,
        }
    }
    pub(crate) fn with_capacity(n: i64) -> Self {
        Self {
            bytes: Vec::with_capacity(n.max(0) as usize),
            pos: 0,
        }
    }
    pub(crate) fn from(bytes: &Vec<u8>) -> Self {
        Self {
            bytes: bytes.clone(),
            pos: 0,
        }
    }
    pub(crate) fn write_u8(&mut self, v: u8) {
        self.bytes.push(v);
    }
    pub(crate) fn write_byte(&mut self, v: u8) {
        self.write_u8(v);
    }
    pub(crate) fn write_u16_le(&mut self, v: u16) {
        self.bytes.extend_from_slice(&v.to_le_bytes());
    }
    pub(crate) fn write_u16_be(&mut self, v: u16) {
        self.bytes.extend_from_slice(&v.to_be_bytes());
    }
    pub(crate) fn write_u32_le(&mut self, v: u32) {
        self.bytes.extend_from_slice(&v.to_le_bytes());
    }
    pub(crate) fn write_u32_be(&mut self, v: u32) {
        self.bytes.extend_from_slice(&v.to_be_bytes());
    }
    pub(crate) fn write_u64_le(&mut self, v: u64) {
        self.bytes.extend_from_slice(&v.to_le_bytes());
    }
    pub(crate) fn write_u64_be(&mut self, v: u64) {
        self.bytes.extend_from_slice(&v.to_be_bytes());
    }
    pub(crate) fn write_bytes(&mut self, bytes: &Vec<u8>) {
        self.bytes.extend_from_slice(bytes);
    }
    pub(crate) fn write(&mut self, bytes: &Vec<u8>) {
        self.write_bytes(bytes);
    }
    pub(crate) fn write_to(&mut self, other: &mut JetByteBuffer) {
        other.bytes.extend_from_slice(&self.bytes);
    }
    pub(crate) fn to_bytes(&self) -> Vec<u8> {
        self.bytes.clone()
    }
    pub(crate) fn get_buffer(&self) -> Vec<u8> {
        self.bytes.clone()
    }
    pub(crate) fn buffer(&self) -> Vec<u8> {
        self.bytes.clone()
    }
    pub(crate) fn capacity(&self) -> i64 {
        self.bytes.capacity() as i64
    }
    pub(crate) fn len(&self) -> i64 {
        self.bytes.len() as i64
    }
    pub(crate) fn is_empty(&self) -> bool {
        self.bytes.is_empty()
    }
    pub(crate) fn clear(&mut self) {
        self.bytes.clear();
        self.pos = 0;
    }
    pub(crate) fn position(&self) -> i64 {
        self.pos as i64
    }
    pub(crate) fn eof(&self) -> bool {
        self.pos >= self.bytes.len()
    }
    pub(crate) fn rewind(&mut self) {
        self.pos = 0;
    }
    pub(crate) fn seek(&mut self, index: i64) {
        if index <= 0 {
            self.pos = 0;
        } else if (index as usize) > self.bytes.len() {
            self.pos = self.bytes.len();
        } else {
            self.pos = index as usize;
        }
    }
    pub(crate) fn get(&self, index: i64) -> JetOutcome<u8, JetAbsent> {
        if index < 0 {
            return Err(JetAbsent);
        }
        jet_outcome_of(self.bytes.get(index as usize).copied())
    }
    pub(crate) fn first(&self) -> JetOutcome<u8, JetAbsent> {
        jet_outcome_of(self.bytes.first().copied())
    }
    pub(crate) fn next(&mut self) -> JetOutcome<u8, JetAbsent> {
        self.read_byte()
    }
    pub(crate) fn read_byte(&mut self) -> JetOutcome<u8, JetAbsent> {
        if self.pos >= self.bytes.len() {
            return Err(JetAbsent);
        }
        let b = self.bytes[self.pos];
        self.pos += 1;
        Ok(b)
    }
    pub(crate) fn read_bytes(&mut self, n: i64) -> JetOutcome<Vec<u8>, JetAbsent> {
        if n < 0 {
            return Err(JetAbsent);
        }
        let n = n as usize;
        if self.pos + n > self.bytes.len() {
            return Err(JetAbsent);
        }
        let out = self.bytes[self.pos..self.pos + n].to_vec();
        self.pos += n;
        Ok(out)
    }
    pub(crate) fn read(&mut self) -> JetOutcome<Vec<u8>, JetAbsent> {
        if self.eof() {
            return Err(JetAbsent);
        }
        let out = self.bytes[self.pos..].to_vec();
        self.pos = self.bytes.len();
        Ok(out)
    }
    pub(crate) fn read_string(&mut self, n: i64) -> JetOutcome<String, JetAbsent> {
        self.read_bytes(n)
            .map(|b| String::from_utf8_lossy(&b).into_owned())
    }
    pub(crate) fn as_text(&self) -> String {
        String::from_utf8_lossy(&self.bytes).into_owned()
    }
    pub(crate) fn to_string(&self) -> String {
        self.as_text()
    }
    pub(crate) fn string(&self) -> String {
        self.as_text()
    }
    pub(crate) fn contains(&self, needle: &String) -> bool {
        self.as_text().contains(needle.as_str())
    }
    pub(crate) fn starts_with(&self, prefix: &String) -> bool {
        self.as_text().starts_with(prefix.as_str())
    }
    pub(crate) fn ends_with(&self, suffix: &String) -> bool {
        self.as_text().ends_with(suffix.as_str())
    }
    pub(crate) fn trim(&self) -> JetByteBuffer {
        JetByteBuffer::from(&self.as_text().trim().as_bytes().to_vec())
    }
    pub(crate) fn trim_start(&self) -> JetByteBuffer {
        JetByteBuffer::from(&self.as_text().trim_start().as_bytes().to_vec())
    }
    pub(crate) fn trim_end(&self) -> JetByteBuffer {
        JetByteBuffer::from(&self.as_text().trim_end().as_bytes().to_vec())
    }
    pub(crate) fn to_lower(&self) -> JetByteBuffer {
        JetByteBuffer::from(&self.as_text().to_lowercase().into_bytes())
    }
    pub(crate) fn to_upper(&self) -> JetByteBuffer {
        JetByteBuffer::from(&self.as_text().to_uppercase().into_bytes())
    }
    pub(crate) fn to_title(&self) -> JetByteBuffer {
        let s = self.as_text();
        let mut out = String::with_capacity(s.len());
        let mut start = true;
        for ch in s.chars() {
            if ch.is_whitespace() {
                start = true;
                out.push(ch);
            } else if start {
                for c in ch.to_uppercase() {
                    out.push(c);
                }
                start = false;
            } else {
                for c in ch.to_lowercase() {
                    out.push(c);
                }
            }
        }
        JetByteBuffer::from(&out.into_bytes())
    }
    pub(crate) fn title(&self) -> JetByteBuffer {
        self.to_title()
    }
    pub(crate) fn replace(&self, from: &String, to: &String) -> JetByteBuffer {
        JetByteBuffer::from(&self.as_text().replace(from.as_str(), to.as_str()).into_bytes())
    }
    pub(crate) fn split(&self, sep: &String) -> Vec<String> {
        let text = self.as_text();
        if sep.is_empty() {
            let mut out = vec![String::new()];
            for ch in text.chars() {
                out.push(ch.to_string());
            }
            out.push(String::new());
            return out;
        }
        text.split(sep.as_str()).map(|s| s.to_string()).collect()
    }
    pub(crate) fn join(&self, parts: &Vec<String>) -> JetByteBuffer {
        JetByteBuffer::from(&parts.join(&self.as_text()).into_bytes())
    }
    pub(crate) fn lines(&self) -> Vec<String> {
        self.as_text().lines().map(|s| s.to_string()).collect()
    }
    pub(crate) fn index_of(&self, needle: &String) -> JetOutcome<i64, JetAbsent> {
        jet_outcome_of(self.as_text().find(needle.as_str()).map(|i| i as i64))
    }
    pub(crate) fn last_index_of(&self, needle: &String) -> JetOutcome<i64, JetAbsent> {
        jet_outcome_of(self.as_text().rfind(needle.as_str()).map(|i| i as i64))
    }
    pub(crate) fn is_ascii(&self) -> bool {
        self.bytes.is_ascii()
    }
    pub(crate) fn copy(&self) -> JetByteBuffer {
        self.clone()
    }
    pub(crate) fn copy_to(&self, other: &mut JetByteBuffer) {
        other.bytes = self.bytes.clone();
        other.pos = 0;
    }
    pub(crate) fn equal(&self, other: &JetByteBuffer) -> bool {
        self.bytes == other.bytes
    }
    pub(crate) fn compare(&self, other: &JetByteBuffer) -> i64 {
                match self.bytes.cmp(&other.bytes) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        }
    }
    pub(crate) fn parse(&self) -> Result<i64, String> {
        self.as_text()
            .trim()
            .parse::<i64>()
            .map_err(|e| e.to_string())
    }
    pub(crate) fn flush(&mut self) {}
    pub(crate) fn close(&mut self) {
        self.clear();
    }
    pub(crate) fn shutdown(&mut self) {
        self.clear();
    }
}
/// Shared directory-queue kernel for filesystem walks.
///
/// Consumers provide only entry and error carriers. Traversal policy stays
/// here so AOT, JIT, and interpreter adapters cannot drift.
pub(crate) fn jet_fs_walk_parallel<T, E, MakeEntry, MakeError>(
    path: &str,
    shown: &str,
    make_entry: MakeEntry,
    make_error: MakeError,
) -> Result<Vec<T>, E>
where
    T: Send + 'static,
    E: Send + 'static,
    MakeEntry: Fn(String, String, bool, i64) -> T + Send + Sync + 'static,
    MakeError: Fn(&str, std::io::Error) -> E + Send + Sync + 'static,
{
    use std::collections::VecDeque;
    use std::path::PathBuf;
    use std::sync::{Arc, Condvar, Mutex};

    struct QueueState<E> {
        directories: VecDeque<(PathBuf, i64)>,
        active_workers: usize,
        error: Option<E>,
    }

    let root = PathBuf::from(path);
    let state = Arc::new((
        Mutex::new(QueueState {
            directories: VecDeque::from([(root.clone(), 0)]),
            active_workers: 0,
            error: None,
        }),
        Condvar::new(),
    ));
    let sink = Arc::new(Mutex::new(Vec::new()));
    let shown = Arc::new(shown.to_string());
    let make_entry = Arc::new(make_entry);
    let make_error = Arc::new(make_error);
    let workers = std::thread::available_parallelism()
        .map(std::num::NonZeroUsize::get)
        .unwrap_or(1);
    let mut handles = Vec::with_capacity(workers);

    for _ in 0..workers {
        let state = Arc::clone(&state);
        let sink = Arc::clone(&sink);
        let shown = Arc::clone(&shown);
        let make_entry = Arc::clone(&make_entry);
        let make_error = Arc::clone(&make_error);
        let root = root.clone();
        handles.push(std::thread::spawn(move || loop {
            let (dir, depth) = {
                let (queue, wake) = &*state;
                let mut queue = queue
                    .lock()
                    .unwrap_or_else(|_| panic!("filesystem walk queue poisoned"));
                loop {
                    if queue.error.is_some() {
                        return;
                    }
                    if let Some(task) = queue.directories.pop_front() {
                        queue.active_workers += 1;
                        break task;
                    }
                    if queue.active_workers == 0 {
                        wake.notify_all();
                        return;
                    }
                    queue = wake
                        .wait(queue)
                        .unwrap_or_else(|_| panic!("filesystem walk queue poisoned"));
                }
            };

            let result = (|| {
                let mut entries = Vec::new();
                for entry in std::fs::read_dir(&dir).map_err(|error| make_error(&shown, error))? {
                    entries.push(entry.map_err(|error| make_error(&shown, error))?);
                }
                let mut batch = Vec::with_capacity(entries.len());
                let mut children = Vec::new();
                for entry in entries {
                    let child = entry.path();
                    let is_dir = entry.file_type().map(|kind| kind.is_dir()).unwrap_or(false);
                    let relative = child
                        .strip_prefix(&root)
                        .unwrap_or(&child)
                        .to_string_lossy()
                        .to_string();
                    batch.push(make_entry(
                        child.to_string_lossy().to_string(),
                        relative,
                        is_dir,
                        depth,
                    ));
                    if is_dir {
                        children.push((child, depth + 1));
                    }
                }
                Ok((batch, children))
            })();

            let (queue, wake) = &*state;
            let mut queue = queue
                .lock()
                .unwrap_or_else(|_| panic!("filesystem walk queue poisoned"));
            queue.active_workers -= 1;
            match result {
                Ok((batch, children)) => {
                    queue.directories.extend(children);
                    drop(queue);
                    sink.lock()
                        .unwrap_or_else(|_| panic!("filesystem walk sink poisoned"))
                        .extend(batch);
                }
                Err(error) => queue.error = Some(error),
            }
            wake.notify_all();
        }));
    }

    for handle in handles {
        if handle.join().is_err() {
            let (queue, _) = &*state;
            let mut queue = queue
                .lock()
                .unwrap_or_else(|_| panic!("filesystem walk queue poisoned"));
            if queue.error.is_none() {
                queue.error = Some(make_error(
                    &shown,
                    std::io::Error::new(
                        std::io::ErrorKind::Other,
                        "parallel walk worker panicked",
                    ),
                ));
            }
        }
    }

    let (queue, _) = &*state;
    let mut queue = queue
        .lock()
        .unwrap_or_else(|_| panic!("filesystem walk queue poisoned"));
    if let Some(error) = queue.error.take() {
        return Err(error);
    }
    let sink = match Arc::try_unwrap(sink) {
        Ok(sink) => sink,
        Err(_) => panic!("filesystem walk sink still referenced"),
    };
    Ok(sink
        .into_inner()
        .unwrap_or_else(|_| panic!("filesystem walk sink poisoned")))
}
/// Shared zip-family policy. Engines only marshal values into this policy;
/// length selection, strict mismatch, and padding indexes stay identical.
fn jet_zip_row_count(lengths: &[usize], mode: u8) -> Option<usize> {
    if lengths.is_empty() {
        return Some(0);
    }
    if mode == 1 && lengths.iter().any(|length| *length != lengths[0]) {
        return None;
    }
    Some(match mode {
        2 => lengths.iter().copied().max().unwrap_or(0),
        _ => lengths.iter().copied().min().unwrap_or(0),
    })
}

fn jet_zip_column_index(row: usize, length: usize) -> Option<usize> {
    (row < length).then_some(row)
}

fn jet_zip_fill_at<T: Clone>(
    fill_mode: u8,
    common_fills: &[T],
    column_fills: &[T],
    default: T,
    column: usize,
) -> T {
    match fill_mode {
        1 => common_fills.get(column).cloned().unwrap_or(default),
        2 => column_fills.get(column).cloned().unwrap_or(default),
        _ => default,
    }
}

fn jet_zip_rows<T: Clone, Read, Fill>(
    lengths: &[usize],
    mode: u8,
    mut read: Read,
    mut fill: Fill,
) -> Option<Vec<Vec<T>>>
where
    Read: FnMut(usize, usize) -> Option<T>,
    Fill: FnMut(usize) -> T,
{
    let row_count = jet_zip_row_count(lengths, mode)?;
    Some(
        (0..row_count)
            .map(|row| {
                lengths
                    .iter()
                    .enumerate()
                    .map(|(column, length)| {
                        jet_zip_column_index(row, *length)
                            .and_then(|index| read(column, index))
                            .unwrap_or_else(|| fill(column))
                    })
                    .collect()
            })
            .collect(),
    )
}

fn jet_zip_strict_step<A, B>(left: Option<A>, right: Option<B>) -> Result<Option<(A, B)>, ()> {
    match (left, right) {
        (Some(left), Some(right)) => Ok(Some((left, right))),
        (None, None) => Ok(None),
        (None, Some(_)) | (Some(_), None) => Err(()),
    }
}

fn jet_zip_pad_step<A: Clone, B: Clone>(
    left: Option<A>,
    right: Option<B>,
    left_fill: A,
    right_fill: B,
) -> Option<(A, B)> {
    match (left, right) {
        (Some(left), Some(right)) => Some((left, right)),
        (Some(left), None) => Some((left, right_fill)),
        (None, Some(right)) => Some((left_fill, right)),
        (None, None) => None,
    }
}
