/// D-NUMWIDEN-CROSS1=E: canonical checked integer-to-float widening policy.
///
/// A binary float with `precision` significant bits holds an integer exactly
/// when either the integer fits in that precision or its discarded low bits
/// are all zero. Engines pass the integer's raw bits and signedness; no engine
/// reconstructs this rule.
fn jet_numeric_integer_is_exact(raw: u64, signed: bool, precision: u32) -> bool {
    let magnitude = if signed {
        (raw as i64).unsigned_abs()
    } else {
        raw
    };
    if magnitude == 0 {
        return true;
    }
    let significant = u64::BITS - magnitude.leading_zeros();
    significant <= precision || magnitude.trailing_zeros() >= significant - precision
}

pub const JET_NUMERIC_WIDEN_TRAP: &str =
    "whole number cannot cross into the decimal without losing precision";

pub fn jet_numeric_checked_widen(
    raw: u64,
    signed: bool,
    target_f32: bool,
) -> Option<f64> {
    let precision = if target_f32 { 24 } else { 53 };
    if !jet_numeric_integer_is_exact(raw, signed, precision) {
        return None;
    }
    let value = if signed {
        (raw as i64) as f64
    } else {
        raw as f64
    };
    Some(if target_f32 {
        (value as f32) as f64
    } else {
        value
    })
}

#[cfg(test)]
mod numeric_widen_tests {
    use super::jet_numeric_checked_widen;

    #[test]
    fn checked_widen_accepts_exact_runtime_values_and_rejects_rounding() {
        assert_eq!(
            jet_numeric_checked_widen(9_007_199_254_740_992, true, false),
            Some(9_007_199_254_740_992.0)
        );
        assert_eq!(
            jet_numeric_checked_widen(9_007_199_254_740_993, true, false),
            None
        );
        assert_eq!(
            jet_numeric_checked_widen((-9_007_199_254_740_992i64) as u64, true, false),
            Some(-9_007_199_254_740_992.0)
        );
        assert_eq!(
            jet_numeric_checked_widen((-9_007_199_254_740_993i64) as u64, true, false),
            None
        );
        assert_eq!(
            jet_numeric_checked_widen(16_777_216, false, true),
            Some(16_777_216.0)
        );
        assert_eq!(jet_numeric_checked_widen(16_777_217, false, true), None);
        assert!(jet_numeric_checked_widen(i64::MIN as u64, true, false).is_some());
        assert!(jet_numeric_checked_widen(u64::MAX, false, false).is_none());
    }
}
// D-OBSERVE-LIVE1=A: one live, payload-free runtime snapshot source. Generated
// programs publish bounded runtime facts only when JET_OBSERVE=1. Channel
// values, task locals, environment, and credentials never enter this registry.

#[derive(Clone)]
struct JetObserveTask {
    parent: usize,
    state: &'static str,
    wait: String,
    deadline_ms: Option<i64>,
    cancelled: bool,
}

#[derive(Clone)]
struct JetObserveChannel {
    depth: usize,
    capacity: Option<usize>,
    send_waiters: usize,
    recv_waiters: usize,
    closed: bool,
}

#[derive(Clone)]
struct JetObserveEvent {
    sequence: u64,
    source: &'static str,
    event_id: u64,
    owner_id: u64,
    subscription_id: u64,
    dispatch_id: u64,
    lifecycle: &'static str,
    queued: i64,
    blocked: i64,
    running: i64,
    capacity: i64,
    overflow: &'static str,
    priority: i64,
    failure: &'static str,
    terminal: &'static str,
}

const JET_OBSERVE_EVENT_LIMIT: usize = 256;

struct JetObserveRegistry {
    next_task: std::sync::atomic::AtomicUsize,
    next_channel: std::sync::atomic::AtomicUsize,
    next_event_sequence: std::sync::atomic::AtomicU64,
    tasks: std::sync::Mutex<std::collections::HashMap<usize, JetObserveTask>>,
    channels: std::sync::Mutex<std::collections::HashMap<usize, JetObserveChannel>>,
    events: std::sync::Mutex<std::collections::VecDeque<JetObserveEvent>>,
}

static JET_OBSERVE: std::sync::OnceLock<Option<std::sync::Arc<JetObserveRegistry>>> =
    std::sync::OnceLock::new();
static JET_OBSERVE_STARTED: std::sync::OnceLock<()> = std::sync::OnceLock::new();
static JET_OBSERVE_ARENAS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static JET_OBSERVE_ARENA_ALLOCS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static JET_OBSERVE_ARENA_BYTES: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
// #648 runtime-only allocator memory measurements. These deliberately do not
// add snapshot schema/policy vocabulary; D-MEM-FACTS1 owns any public fact.
static JET_OBSERVE_ARENA_RETAINED_BYTES: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static JET_OBSERVE_ARENA_HIGH_WATER_BYTES: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static JET_OBSERVE_WORKERS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static JET_OBSERVE_QUEUED: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
// AllocationProbe uses a separate resettable window. Live-inspector counters
// remain outstanding-resource facts; probe reset/take cannot corrupt them.
static JET_PROBE_ARENA_ALLOCS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static JET_PROBE_ARENA_BYTES: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

thread_local! {
    pub static JET_OBSERVE_TASK_ID: std::cell::Cell<usize> = const { std::cell::Cell::new(1) };
}

fn jet_observe_registry() -> Option<&'static std::sync::Arc<JetObserveRegistry>> {
    JET_OBSERVE
        .get_or_init(|| {
            (std::env::var("JET_OBSERVE").ok().as_deref() == Some("1")).then(|| {
                std::sync::Arc::new(JetObserveRegistry {
                    next_task: std::sync::atomic::AtomicUsize::new(2),
                    next_channel: std::sync::atomic::AtomicUsize::new(1),
                    next_event_sequence: std::sync::atomic::AtomicU64::new(1),
                    tasks: std::sync::Mutex::new(std::collections::HashMap::new()),
                    channels: std::sync::Mutex::new(std::collections::HashMap::new()),
                    events: std::sync::Mutex::new(std::collections::VecDeque::new()),
                })
            })
        })
        .as_ref()
}

fn jet_observe_escape(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars().take(160) {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' | '\r' | '\t' => out.push(' '),
            c if c.is_control() => out.push(' '),
            c => out.push(c),
        }
    }
    out
}

fn jet_observe_process_start_id() -> String {
    #[cfg(any(target_os = "linux", target_os = "android"))]
    if let Ok(stat) = std::fs::read_to_string("/proc/self/stat") {
        if let Some(value) = stat
            .rsplit_once(") ")
            .and_then(|(_, tail)| tail.split_whitespace().nth(19))
        {
            return value.to_string();
        }
    }
    String::new()
}

fn jet_observe_snapshot(registry: &JetObserveRegistry, start_id: &str) -> String {
    use std::sync::atomic::Ordering;
    let mut tasks: Vec<_> = registry.tasks.lock().unwrap().iter()
        .map(|(id, task)| (*id, task.clone())).collect();
    tasks.sort_by_key(|(id, _)| *id);
    let mut channels: Vec<_> = registry.channels.lock().unwrap().iter()
        .map(|(id, channel)| (*id, channel.clone())).collect();
    channels.sort_by_key(|(id, _)| *id);
    let events = registry.events.lock().unwrap().iter().cloned().collect::<Vec<_>>();
    tasks.truncate(4096);
    channels.truncate(4096);

    let task_json = tasks.iter().map(|(id, task)| format!(
        "{{\"id\":{id},\"parent\":{},\"state\":\"{}\",\"wait\":\"{}\",\"deadline_ms\":{},\"cancelled\":{}}}",
        task.parent, task.state, jet_observe_escape(&task.wait),
        task.deadline_ms.map(|v| v.to_string()).unwrap_or_else(|| "null".to_string()),
        task.cancelled
    )).collect::<Vec<_>>().join(",");
    let channel_json = channels.iter().map(|(id, channel)| format!(
        "{{\"id\":{id},\"depth\":{},\"capacity\":{},\"send_waiters\":{},\"recv_waiters\":{},\"closed\":{}}}",
        channel.depth,
        channel.capacity.map(|v| v.to_string()).unwrap_or_else(|| "null".to_string()),
        channel.send_waiters, channel.recv_waiters, channel.closed
    )).collect::<Vec<_>>().join(",");
    let event_json = events.iter().map(|event| format!(
        "{{\"sequence\":{},\"source\":\"{}\",\"event_id\":{},\"owner_id\":{},\"subscription_id\":{},\"dispatch_id\":{},\"lifecycle\":\"{}\",\"queued\":{},\"blocked\":{},\"running\":{},\"capacity\":{},\"overflow\":\"{}\",\"priority\":{},\"failure\":\"{}\",\"terminal\":\"{}\"}}",
        event.sequence, event.source, event.event_id, event.owner_id,
        event.subscription_id, event.dispatch_id, event.lifecycle, event.queued,
        event.blocked, event.running, event.capacity, event.overflow,
        event.priority, event.failure, event.terminal
    )).collect::<Vec<_>>().join(",");
    let blocked = tasks.iter().filter(|(_, task)| task.state == "blocked").count();
    let channel_waits = tasks.iter().filter(|(_, task)|
        task.state == "blocked" && task.wait.starts_with("channel ")).count();
    let time_waits = tasks.iter().filter(|(_, task)|
        task.state == "blocked" && task.wait.starts_with("time ")).count();
    let io_waits = tasks.iter().filter(|(_, task)| task.state == "blocked" &&
        (task.wait.contains("tcp") || task.wait.contains("network") || task.wait.starts_with("io "))
    ).count();
    let cancelled = tasks.iter().filter(|(_, task)| task.cancelled).count();
    let running = tasks.iter().filter(|(_, task)| task.state == "running").count();

    format!(
        "{{\"schema_version\":1,\"pid\":{},\"start_id\":\"{}\",\"captured_ms\":{},\"tasks\":[{}],\"channels\":[{}],\"event_observations\":[{}],\"effects\":{{\"compute\":{},\"waiting\":{},\"channel\":{},\"time\":{},\"io\":{}}},\"resources\":{{\"workers\":{},\"running\":{},\"queued\":{},\"cancelled\":{},\"arenas\":{},\"arena_allocations\":{},\"arena_bytes\":{}}}}}",
        std::process::id(),
        start_id,
        std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default().as_millis(),
        task_json, channel_json, event_json,
        tasks.len().saturating_sub(blocked), blocked, channel_waits, time_waits, io_waits,
        JET_OBSERVE_WORKERS.load(Ordering::Relaxed),
        running, JET_OBSERVE_QUEUED.load(Ordering::Relaxed), cancelled,
        JET_OBSERVE_ARENAS.load(Ordering::Relaxed),
        JET_OBSERVE_ARENA_ALLOCS.load(Ordering::Relaxed),
        JET_OBSERVE_ARENA_BYTES.load(Ordering::Relaxed)
    )
}

fn jet_observe_event(mut event: JetObserveEvent) {
    use std::sync::atomic::Ordering;
    let Some(registry) = jet_observe_registry() else { return };
    let mut events = registry.events.lock().unwrap();
    event.sequence = registry.next_event_sequence.fetch_add(1, Ordering::Relaxed);
    if events.len() == JET_OBSERVE_EVENT_LIMIT {
        events.pop_front();
    }
    events.push_back(event);
}

pub fn jet_observe_task_register(observe_id: &std::sync::atomic::AtomicUsize) -> usize {
    use std::sync::atomic::Ordering;
    let Some(registry) = jet_observe_registry() else {
        observe_id.store(0, Ordering::Relaxed);
        return 0;
    };
    let parent = JET_OBSERVE_TASK_ID.with(|current| current.get());
    let id = registry.next_task.fetch_add(1, Ordering::Relaxed);
    registry.tasks.lock().unwrap().insert(
        id,
        JetObserveTask {
            parent,
            state: "queued",
            wait: String::new(),
            deadline_ms: None,
            cancelled: false,
        },
    );
    observe_id.store(id, Ordering::Relaxed);
    id
}

pub fn jet_observe_task_enter(id: usize) {
    if id == 0 {
        return;
    }
    JET_OBSERVE_TASK_ID.with(|current| current.set(id));
    if let Some(registry) = jet_observe_registry() {
        if let Some(task) = registry.tasks.lock().unwrap().get_mut(&id) {
            task.state = "running";
        }
    }
}

pub fn jet_observe_task_finish(id: usize) {
    if id == 0 {
        return;
    }
    if let Some(registry) = jet_observe_registry() {
        registry.tasks.lock().unwrap().remove(&id);
    }
}

pub fn jet_observe_runtime_start() {
    let Some(registry) = jet_observe_registry().cloned() else { return };
    if JET_OBSERVE_STARTED.set(()).is_err() {
        return;
    }
    registry.tasks.lock().unwrap().insert(1, JetObserveTask {
        parent: 0, state: "running", wait: String::new(), deadline_ms: None, cancelled: false,
    });
    std::thread::spawn(move || {
        use std::io::Write;
        let pid = std::process::id();
        let start_id = jet_observe_process_start_id();
        let path = std::env::temp_dir().join(format!("jet-observe-{pid}.json"));
        let mut sequence = 0_u64;
        loop {
            sequence = sequence.wrapping_add(1);
            let snapshot = jet_observe_snapshot(&registry, &start_id);
            let staging = std::env::temp_dir().join(format!(
                ".jet-observe-{pid}-{start_id}-{sequence}.tmp"
            ));
            let mut options = std::fs::OpenOptions::new();
            options.write(true).create_new(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt;
                options.mode(0o600);
            }
            if snapshot.len() <= 1024 * 1024 {
                if let Ok(mut file) = options.open(&staging) {
                    if file.write_all(snapshot.as_bytes()).is_ok() && file.sync_all().is_ok() {
                        let _ = std::fs::rename(&staging, &path);
                    }
                }
            }
            let _ = std::fs::remove_file(&staging);
            std::thread::sleep(std::time::Duration::from_millis(100));
        }
    });
}

fn jet_observe_task_update(state: &'static str, wait: &str, deadline_ms: Option<i64>) {
    let Some(registry) = jet_observe_registry() else { return };
    let id = JET_OBSERVE_TASK_ID.with(|current| current.get());
    if let Some(task) = registry.tasks.lock().unwrap().get_mut(&id) {
        task.state = state;
        task.wait = wait.chars().take(160).collect();
        task.deadline_ms = deadline_ms;
    }
}

fn jet_observe_arena_open() {
    JET_OBSERVE_ARENAS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
}
fn jet_observe_arena_alloc(bytes: usize) {
    JET_OBSERVE_ARENA_ALLOCS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let live = JET_OBSERVE_ARENA_BYTES
        .fetch_add(bytes, std::sync::atomic::Ordering::Relaxed)
        .saturating_add(bytes);
    JET_OBSERVE_ARENA_HIGH_WATER_BYTES.fetch_max(live, std::sync::atomic::Ordering::Relaxed);
    JET_PROBE_ARENA_ALLOCS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    JET_PROBE_ARENA_BYTES.fetch_add(bytes, std::sync::atomic::Ordering::Relaxed);
}
fn jet_observe_arena_retain(bytes: usize) {
    JET_OBSERVE_ARENA_RETAINED_BYTES.fetch_add(bytes, std::sync::atomic::Ordering::Relaxed);
}
fn jet_observe_arena_release(bytes: usize) {
    JET_OBSERVE_ARENA_RETAINED_BYTES.fetch_sub(bytes, std::sync::atomic::Ordering::Relaxed);
}
fn jet_observe_allocator_memory() -> (usize, usize) {
    (
        JET_OBSERVE_ARENA_RETAINED_BYTES.load(std::sync::atomic::Ordering::Relaxed),
        JET_OBSERVE_ARENA_HIGH_WATER_BYTES.load(std::sync::atomic::Ordering::Relaxed),
    )
}
fn jet_observe_arena_reset(allocations: usize, bytes: usize) {
    JET_OBSERVE_ARENA_ALLOCS.fetch_sub(allocations, std::sync::atomic::Ordering::Relaxed);
    JET_OBSERVE_ARENA_BYTES.fetch_sub(bytes, std::sync::atomic::Ordering::Relaxed);
}
fn jet_observe_arena_close() {
    JET_OBSERVE_ARENAS.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
}

fn jet_allocation_probe_reset() {
    JET_PROBE_ARENA_ALLOCS.store(0, std::sync::atomic::Ordering::SeqCst);
    JET_PROBE_ARENA_BYTES.store(0, std::sync::atomic::Ordering::SeqCst);
}

fn jet_allocation_probe_take() -> (usize, usize) {
    (
        JET_PROBE_ARENA_ALLOCS.swap(0, std::sync::atomic::Ordering::SeqCst),
        JET_PROBE_ARENA_BYTES.swap(0, std::sync::atomic::Ordering::SeqCst),
    )
}
// Exact runtime proof for unit conversions, shared by JIT and emitted AOT code.

#[derive(Clone)]
struct Integer {
    sign: i8,
    limbs: Vec<u32>,
}

impl Integer {
    const BASE: u64 = 1_000_000_000;
    fn zero() -> Self {
        Self {
            sign: 0,
            limbs: Vec::new(),
        }
    }
    fn one() -> Self {
        Self::from_u64(1)
    }
    fn from_u64(mut value: u64) -> Self {
        if value == 0 {
            return Self::zero();
        }
        let mut limbs = Vec::new();
        while value != 0 {
            limbs.push((value % Self::BASE) as u32);
            value /= Self::BASE;
        }
        Self { sign: 1, limbs }
    }
    fn parse(text: &str) -> Option<Self> {
        let (sign, digits) = text
            .strip_prefix('-')
            .map_or((1, text), |digits| (-1, digits));
        if digits.is_empty() || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
            return None;
        }
        let mut value = Self::zero();
        for byte in digits.bytes() {
            value = value
                .mul_small(10)
                .add(&Self::from_u64(u64::from(byte - b'0')));
        }
        if !value.is_zero() {
            value.sign = sign;
        }
        Some(value)
    }
    fn is_zero(&self) -> bool {
        self.sign == 0
    }
    fn is_odd(&self) -> bool {
        self.limbs.first().is_some_and(|limb| limb % 2 == 1)
    }
    fn neg(mut self) -> Self {
        self.sign = -self.sign;
        self
    }
    fn normalize(&mut self) {
        while self.limbs.last() == Some(&0) {
            self.limbs.pop();
        }
        if self.limbs.is_empty() {
            self.sign = 0;
        }
    }
    fn abs(&self) -> Self {
        let mut value = self.clone();
        if !value.is_zero() {
            value.sign = 1;
        }
        value
    }
    fn abs_cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.limbs
            .len()
            .cmp(&other.limbs.len())
            .then_with(|| self.limbs.iter().rev().cmp(other.limbs.iter().rev()))
    }
    fn abs_add(&self, other: &Self) -> Self {
        let mut carry = 0;
        let mut limbs = Vec::with_capacity(self.limbs.len().max(other.limbs.len()) + 1);
        for index in 0..self.limbs.len().max(other.limbs.len()) {
            let value = u64::from(*self.limbs.get(index).unwrap_or(&0))
                + u64::from(*other.limbs.get(index).unwrap_or(&0))
                + carry;
            limbs.push((value % Self::BASE) as u32);
            carry = value / Self::BASE;
        }
        if carry != 0 {
            limbs.push(carry as u32);
        }
        Self { sign: 1, limbs }
    }
    fn abs_sub(&self, other: &Self) -> Self {
        let mut borrow = 0;
        let mut limbs = Vec::with_capacity(self.limbs.len());
        for index in 0..self.limbs.len() {
            let mut value = i64::from(self.limbs[index])
                - i64::from(*other.limbs.get(index).unwrap_or(&0))
                - borrow;
            if value < 0 {
                value += Self::BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            limbs.push(value as u32);
        }
        let mut value = Self { sign: 1, limbs };
        value.normalize();
        value
    }
    fn add(&self, other: &Self) -> Self {
        if self.is_zero() {
            return other.clone();
        }
        if other.is_zero() {
            return self.clone();
        }
        if self.sign == other.sign {
            let mut value = self.abs_add(other);
            value.sign = self.sign;
            value
        } else {
            match self.abs_cmp(other) {
                std::cmp::Ordering::Greater => {
                    let mut value = self.abs_sub(other);
                    value.sign = self.sign;
                    value
                }
                std::cmp::Ordering::Less => {
                    let mut value = other.abs_sub(self);
                    value.sign = other.sign;
                    value
                }
                std::cmp::Ordering::Equal => Self::zero(),
            }
        }
    }
    fn mul_small(&self, other: u32) -> Self {
        if other == 0 || self.is_zero() {
            return Self::zero();
        }
        let mut carry = 0;
        let mut limbs = Vec::with_capacity(self.limbs.len() + 1);
        for limb in &self.limbs {
            let value = u64::from(*limb) * u64::from(other) + carry;
            limbs.push((value % Self::BASE) as u32);
            carry = value / Self::BASE;
        }
        if carry != 0 {
            limbs.push(carry as u32);
        }
        Self {
            sign: self.sign,
            limbs,
        }
    }
    fn mul(&self, other: &Self) -> Self {
        if self.is_zero() || other.is_zero() {
            return Self::zero();
        }
        let mut limbs = vec![0u64; self.limbs.len() + other.limbs.len()];
        for (left_index, left) in self.limbs.iter().enumerate() {
            let mut carry = 0;
            for (right_index, right) in other.limbs.iter().enumerate() {
                let index = left_index + right_index;
                let value = limbs[index] + u64::from(*left) * u64::from(*right) + carry;
                limbs[index] = value % Self::BASE;
                carry = value / Self::BASE;
            }
            limbs[left_index + other.limbs.len()] += carry;
        }
        let mut value = Self {
            sign: self.sign * other.sign,
            limbs: limbs.into_iter().map(|limb| limb as u32).collect(),
        };
        value.normalize();
        value
    }
    fn mul_pow2(mut self, exponent: u32) -> Self {
        for _ in 0..exponent {
            self = self.mul_small(2);
        }
        self
    }
    fn div_rem_abs(&self, other: &Self) -> Option<(Self, Self)> {
        if other.is_zero() {
            return None;
        }
        let divisor = other.abs();
        let dividend = self.abs();
        if dividend.abs_cmp(&divisor) == std::cmp::Ordering::Less {
            return Some((Self::zero(), dividend));
        }
        let mut quotient = vec![0; dividend.limbs.len()];
        let mut remainder = Self::zero();
        for index in (0..dividend.limbs.len()).rev() {
            remainder.limbs.insert(0, dividend.limbs[index]);
            remainder.sign = 1;
            remainder.normalize();
            let (mut low, mut high) = (0, (Self::BASE - 1) as u32);
            while low < high {
                let middle = low + (high - low) / 2 + 1;
                if divisor.mul_small(middle).abs_cmp(&remainder) != std::cmp::Ordering::Greater {
                    low = middle;
                } else {
                    high = middle - 1;
                }
            }
            quotient[index] = low;
            if low != 0 {
                remainder = remainder.abs_sub(&divisor.mul_small(low));
            }
        }
        let mut quotient = Self {
            sign: 1,
            limbs: quotient,
        };
        quotient.normalize();
        Some((quotient, remainder))
    }
    fn decimal(&self) -> String {
        if self.is_zero() {
            return "0".to_string();
        }
        let mut limbs = self.limbs.iter().rev();
        let mut text = limbs.next().expect("nonzero integer has limbs").to_string();
        for limb in limbs {
            text.push_str(&format!("{limb:09}"));
        }
        if self.sign < 0 {
            text.insert(0, '-');
        }
        text
    }
}

fn float_ratio(value: f64) -> Option<(Integer, Integer)> {
    if !value.is_finite() {
        return None;
    }
    let bits = value.to_bits();
    let exponent_bits = ((bits >> 52) & 0x7ff) as i32;
    let fraction = bits & ((1_u64 << 52) - 1);
    let (significand, exponent) = if exponent_bits == 0 {
        (fraction, -1074)
    } else {
        ((1_u64 << 52) | fraction, exponent_bits - 1023 - 52)
    };
    let mut numerator = Integer::from_u64(significand);
    if bits >> 63 != 0 && !numerator.is_zero() {
        numerator.sign = -1;
    }
    let mut denominator = Integer::one();
    if exponent >= 0 {
        numerator = numerator.mul_pow2(exponent as u32);
    } else {
        denominator = denominator.mul_pow2((-exponent) as u32);
    }
    Some((numerator, denominator))
}

fn converted_ratio(
    value: f64,
    scale_num: &str,
    scale_den: &str,
    offset_num: &str,
    offset_den: &str,
) -> Option<(Integer, Integer)> {
    let (value_num, value_den) = float_ratio(value)?;
    let scale_num = Integer::parse(scale_num)?;
    let scale_den = Integer::parse(scale_den)?;
    let offset_num = Integer::parse(offset_num)?;
    let offset_den = Integer::parse(offset_den)?;
    if scale_den.is_zero() || offset_den.is_zero() {
        return None;
    }
    let mut numerator = value_num
        .mul(&scale_num)
        .mul(&offset_den)
        .add(&offset_num.mul(&value_den).mul(&scale_den));
    let mut denominator = value_den.mul(&scale_den).mul(&offset_den);
    if denominator.sign < 0 {
        numerator = numerator.neg();
        denominator = denominator.neg();
    }
    Some((numerator, denominator))
}

fn exact_integer(numerator: &Integer, denominator: &Integer) -> Option<Integer> {
    let (mut quotient, remainder) = numerator.div_rem_abs(denominator)?;
    if !remainder.is_zero() {
        return None;
    }
    if !quotient.is_zero() {
        quotient.sign = numerator.sign * denominator.sign;
    }
    Some(quotient)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(i64)]
pub enum UnitRoundingMode {
    TowardZero,
    Floor,
    Ceiling,
    NearestEven,
}

pub const UNIT_ROUNDING_NEGATIVE_DIGITS: &str = "rounded unit conversion needs nonnegative digits";
pub const UNIT_ROUNDING_UNREPRESENTABLE: &str =
    "unit conversion overflows its runtime representation";

// The smallest positive Float is 2^-1074, so every finite Float terminates by
// this many decimal places. Greater precision can be checked without building
// a power of ten proportional to the runtime `digits` value.
const MAX_FINITE_FLOAT_DECIMAL_PLACES: i64 = 1074;

fn rounded_integer(
    numerator: &Integer,
    denominator: &Integer,
    mode: UnitRoundingMode,
) -> Option<Integer> {
    let (mut quotient, remainder) = numerator.div_rem_abs(denominator)?;
    let sign = numerator.sign * denominator.sign;
    let increment = match mode {
        UnitRoundingMode::TowardZero => false,
        UnitRoundingMode::Floor => sign < 0 && !remainder.is_zero(),
        UnitRoundingMode::Ceiling => sign > 0 && !remainder.is_zero(),
        UnitRoundingMode::NearestEven => {
            let comparison = remainder.mul_small(2).abs_cmp(&denominator.abs());
            comparison == std::cmp::Ordering::Greater
                || (comparison == std::cmp::Ordering::Equal && quotient.is_odd())
        }
    };
    if increment {
        quotient = quotient.add(&Integer::one());
    }
    if !quotient.is_zero() {
        quotient.sign = sign;
    }
    Some(quotient)
}

fn decimal_value(integer: &Integer, digits: usize) -> Option<f64> {
    let negative = integer.sign < 0;
    let mut decimal = integer.abs().decimal();
    if digits != 0 {
        if decimal.len() <= digits {
            decimal.insert_str(0, &"0".repeat(digits + 1 - decimal.len()));
        }
        decimal.insert(decimal.len() - digits, '.');
    }
    if negative {
        decimal.insert(0, '-');
    }
    let value = decimal.parse::<f64>().ok()?;
    value.is_finite().then_some(value)
}

fn ratio_cmp(
    left_num: &Integer,
    left_den: &Integer,
    right_num: &Integer,
    right_den: &Integer,
) -> std::cmp::Ordering {
    let difference = left_num.mul(right_den).add(&right_num.mul(left_den).neg());
    difference.sign.cmp(&0)
}

fn float_represents_ratio(value: f64, numerator: &Integer, denominator: &Integer) -> bool {
    float_ratio(value).is_some_and(|(float_num, float_den)| {
        ratio_cmp(numerator, denominator, &float_num, &float_den) == std::cmp::Ordering::Equal
    })
}

fn exactly_represented_float(integer: &Integer) -> Option<f64> {
    let value = integer.decimal().parse::<f64>().ok()?;
    if !value.is_finite() {
        return None;
    }
    float_represents_ratio(value, integer, &Integer::one()).then_some(value)
}

fn exactly_represented_decimal(integer: &Integer, digits: usize) -> Option<f64> {
    let value = decimal_value(integer, digits)?;
    let mut denominator = Integer::one();
    for _ in 0..digits {
        denominator = denominator.mul_small(10);
    }
    float_represents_ratio(value, integer, &denominator).then_some(value)
}

fn ratio_cmp_float(numerator: &Integer, denominator: &Integer, value: f64) -> std::cmp::Ordering {
    let (float_num, float_den) = float_ratio(value).expect("finite Float bound has an exact ratio");
    ratio_cmp(numerator, denominator, &float_num, &float_den)
}

fn positive_float_bounds(numerator: &Integer, denominator: &Integer) -> (f64, bool, Option<f64>) {
    const MAX_FINITE_BITS: u64 = 0x7fefffffffffffff;
    let mut low = 0_u64;
    let mut high = MAX_FINITE_BITS;
    while low < high {
        let middle = low + (high - low) / 2 + 1;
        if ratio_cmp_float(numerator, denominator, f64::from_bits(middle))
            != std::cmp::Ordering::Less
        {
            low = middle;
        } else {
            high = middle - 1;
        }
    }
    let floor = f64::from_bits(low);
    let exact = ratio_cmp_float(numerator, denominator, floor) == std::cmp::Ordering::Equal;
    let ceiling = (!exact && low < MAX_FINITE_BITS).then(|| f64::from_bits(low + 1));
    (floor, exact, ceiling)
}

fn float_bounds(
    numerator: &Integer,
    denominator: &Integer,
) -> (Option<f64>, Option<f64>, Option<f64>) {
    if numerator.is_zero() {
        return (Some(0.0), Some(0.0), Some(0.0));
    }
    let (floor_abs, exact, ceiling_abs) = positive_float_bounds(&numerator.abs(), denominator);
    if exact {
        let value = if numerator.sign < 0 {
            -floor_abs
        } else {
            floor_abs
        };
        return (Some(value), Some(value), Some(value));
    }
    if numerator.sign < 0 {
        (ceiling_abs.map(|value| -value), None, Some(-floor_abs))
    } else {
        (Some(floor_abs), None, ceiling_abs)
    }
}

fn cmp_times_power10(left: &Integer, right: &Integer, power: u64) -> std::cmp::Ordering {
    if left.is_zero() {
        return std::cmp::Ordering::Less;
    }
    let left = left.abs().decimal();
    let right = right.abs().decimal();
    let left_len = left.len() as u128 + power as u128;
    match left_len.cmp(&(right.len() as u128)) {
        std::cmp::Ordering::Equal => {
            let prefix = &right[..left.len()];
            match left.as_str().cmp(prefix) {
                std::cmp::Ordering::Equal => {
                    if right[left.len()..].bytes().all(|byte| byte == b'0') {
                        std::cmp::Ordering::Equal
                    } else {
                        std::cmp::Ordering::Less
                    }
                }
                ordering => ordering,
            }
        }
        ordering => ordering,
    }
}

fn candidate_distance_cmp(
    numerator: &Integer,
    denominator: &Integer,
    candidate: f64,
    digits: u64,
    half_step: bool,
) -> std::cmp::Ordering {
    let (candidate_num, candidate_den) =
        float_ratio(candidate).expect("finite Float candidate has an exact ratio");
    let mut difference = numerator
        .mul(&candidate_den)
        .add(&candidate_num.mul(denominator).neg())
        .abs();
    if half_step {
        difference = difference.mul_small(2);
    }
    cmp_times_power10(&difference, &denominator.mul(&candidate_den), digits)
}

fn huge_precision_rounded_float(
    numerator: &Integer,
    denominator: &Integer,
    mode: UnitRoundingMode,
    digits: u64,
) -> Option<f64> {
    let (lower, exact, upper) = float_bounds(numerator, denominator);
    if exact.is_some() {
        return exact;
    }
    let directed = match mode {
        UnitRoundingMode::TowardZero if numerator.sign < 0 => upper,
        UnitRoundingMode::TowardZero | UnitRoundingMode::Floor => lower,
        UnitRoundingMode::Ceiling => upper,
        UnitRoundingMode::NearestEven => None,
    };
    if mode != UnitRoundingMode::NearestEven {
        return directed.filter(|candidate| {
            candidate_distance_cmp(numerator, denominator, *candidate, digits, false)
                == std::cmp::Ordering::Less
        });
    }
    [lower, upper].into_iter().flatten().find(|candidate| {
        candidate_distance_cmp(numerator, denominator, *candidate, digits, true)
            != std::cmp::Ordering::Greater
    })
}

/// Converts a Float only when exact rational arithmetic proves the result integral.
pub fn jet_unit_conversion_exact(
    value: f64,
    scale_num: &str,
    scale_den: &str,
    offset_num: &str,
    offset_den: &str,
) -> Option<f64> {
    let (numerator, denominator) =
        converted_ratio(value, scale_num, scale_den, offset_num, offset_den)?;
    exactly_represented_float(&exact_integer(&numerator, &denominator)?)
}

/// Applies the declared rational conversion, then rounds to destination decimal places.
pub fn jet_unit_conversion_rounded(
    value: f64,
    scale_num: &str,
    scale_den: &str,
    offset_num: &str,
    offset_den: &str,
    mode: UnitRoundingMode,
    digits: i64,
) -> Result<f64, &'static str> {
    if digits < 0 {
        return Err(UNIT_ROUNDING_NEGATIVE_DIGITS);
    }
    let (mut numerator, denominator) =
        converted_ratio(value, scale_num, scale_den, offset_num, offset_den)
            .ok_or(UNIT_ROUNDING_UNREPRESENTABLE)?;
    if digits > MAX_FINITE_FLOAT_DECIMAL_PLACES {
        return huge_precision_rounded_float(&numerator, &denominator, mode, digits as u64)
            .ok_or(UNIT_ROUNDING_UNREPRESENTABLE);
    }
    let digits = digits as usize;
    for _ in 0..digits {
        numerator = numerator.mul_small(10);
    }
    let integer =
        rounded_integer(&numerator, &denominator, mode).ok_or(UNIT_ROUNDING_UNREPRESENTABLE)?;
    exactly_represented_decimal(&integer, digits).ok_or(UNIT_ROUNDING_UNREPRESENTABLE)
}
/// Debug-only field metadata. Storage layout stays declaration-ordered; this
/// order is the canonical developer-facing shape for `IOContext`.
static IO_CONTEXT_DEBUG_FIELDS: &[&str] = &["operation", "resource", "os_code", "cause"];

/// Core field metadata keeps declaration/storage order and redaction policy
/// separate from developer-facing Debug order.
static IO_CONTEXT_FIELD_METADATA: &[(&str, bool)] = &[
    ("operation", false),
    ("resource", false),
    ("os_code", false),
    ("cause", false),
];

/// Core CBOR parser options are a Prelude record. Keep its declaration order
/// available to JIT and structural-debug adapters when no user item owns it.
static CBOR_OPTIONS_FIELD_METADATA: &[(&str, bool)] = &[
    ("max_depth", false),
    ("max_items", false),
    ("max_bytes", false),
    ("require_canonical", false),
];

static CBOR_ERROR_FIELD_METADATA: &[(&str, bool)] = &[
    ("kind", false),
    ("byte_offset", false),
    ("path", false),
    ("reason", false),
];

static JSON_ERROR_FIELD_METADATA: &[(&str, bool)] = &[("line", false), ("message", false)];

static XML_ERROR_FIELD_METADATA: &[(&str, bool)] = &[
    ("kind", false),
    ("byte_offset", false),
    ("line", false),
    ("column", false),
    ("path", false),
    ("reason", false),
];

static FIELD_ERROR_FIELD_METADATA: &[(&str, bool)] = &[("path", false), ("reason", false)];

static ALLOC_ERROR_FIELD_METADATA: &[(&str, bool)] =
    &[("requested_bytes", false), ("allocator", false)];

/// The one Core structural-type metadata table. `jet_debug_field_metadata`
/// is its keyed view and `jet_debug_field_metadata_rows` its enumeration, so
/// an engine that needs every row (the resident JIT builds its Core struct
/// layout map from them) reads this table instead of copying the keys into a
/// second per-engine list.
static CORE_FIELD_METADATA: &[(&str, &[(&str, bool)])] = &[
    ("IOContext", IO_CONTEXT_FIELD_METADATA),
    ("CBOROptions", CBOR_OPTIONS_FIELD_METADATA),
    ("CBORError", CBOR_ERROR_FIELD_METADATA),
    ("JSONError", JSON_ERROR_FIELD_METADATA),
    ("XMLError", XML_ERROR_FIELD_METADATA),
    ("FieldError", FIELD_ERROR_FIELD_METADATA),
    ("AllocError", ALLOC_ERROR_FIELD_METADATA),
];

/// Return shared field metadata for a core structural type.
pub fn jet_debug_field_metadata(type_name: &str) -> Option<&'static [(&'static str, bool)]> {
    CORE_FIELD_METADATA
        .iter()
        .find(|(name, _)| *name == type_name)
        .map(|(_, fields)| *fields)
}

/// Every row of the table above, in declaration order.
pub fn jet_debug_field_metadata_rows() -> &'static [(&'static str, &'static [(&'static str, bool)])]
{
    CORE_FIELD_METADATA
}

/// Return canonical developer-facing field order for a structural type.
pub fn jet_debug_field_order(type_name: &str) -> Option<&'static [&'static str]> {
    match type_name {
        "IOContext" => Some(IO_CONTEXT_DEBUG_FIELDS),
        _ => None,
    }
}

/// One field marshalled into the shared structural Debug formatter.
/// `storage_index` stays separate from developer-facing order so a runtime
/// adapter can extract declaration-ordered storage without changing Debug.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JetDebugField {
    pub name: String,
    pub value: String,
    pub storage_index: usize,
    pub redacted: bool,
}

/// Assemble the canonical Jet record shape from marshalled fields.
pub fn jet_debug_record_fields(
    type_name: &str,
    fields: impl IntoIterator<Item = JetDebugField>,
) -> String {
    let mut fields = fields.into_iter().collect::<Vec<_>>();
    if let Some(order) = jet_debug_field_order(type_name) {
        fields.sort_by_key(|field| {
            order
                .iter()
                .position(|name| field.name.as_str() == *name)
                .map(|position| (0, position))
                .unwrap_or((1, field.storage_index))
        });
    }
    let fields = fields
        .into_iter()
        .map(|field| {
            let value = if field.redacted {
                "[redacted]"
            } else {
                field.value.as_str()
            };
            format!("{}: {value}", field.name)
        })
        .collect::<Vec<_>>();
    if fields.is_empty() {
        format!("{type_name} {{}}")
    } else {
        format!("{type_name} {{ {} }}", fields.join(", "))
    }
}

/// Assemble the canonical Jet record shape from already-rendered fields.
pub fn jet_debug_record(
    type_name: &str,
    fields: impl IntoIterator<Item = (String, String)>,
) -> String {
    jet_debug_record_fields(
        type_name,
        fields
            .into_iter()
            .enumerate()
            .map(|(storage_index, (name, value))| JetDebugField {
                name,
                value,
                storage_index,
                redacted: false,
            }),
    )
}

/// Assemble the canonical Jet map shape from already-rendered entries.
pub fn jet_debug_map(entries: impl IntoIterator<Item = (String, String)>) -> String {
    let entries = entries
        .into_iter()
        .map(|(key, value)| format!("{key}: {value}"))
        .collect::<Vec<_>>();
    format!("[:{}]", entries.join(", "))
}

/// A structural union renders as its active payload, without a host tag.
pub fn jet_debug_union(payload: String) -> String {
    payload
}

/// Assemble the canonical Jet positional-variant shape from an optional payload.
pub fn jet_debug_variant(variant: &str, payload: Option<String>) -> String {
    match payload {
        Some(payload) => format!("{variant}({payload})"),
        None => variant.to_string(),
    }
}

/// Assemble the canonical Jet optional Debug shape from a rendered payload.
pub fn jet_debug_optional(payload: Option<String>) -> String {
    match payload {
        Some(payload) => format!("Val({payload})"),
        None => "None".to_string(),
    }
}

/// Shared Prelude JetShow projection for the packed `IOError` carrier.
/// `variant` and `operation` use the declaration order of their core enums;
/// resident tiers marshal those discriminants here instead of reformatting
/// the error locally.
pub fn jet_show_io_error(
    variant: i64,
    operation: i64,
    resource: Option<&str>,
    cause: Option<&str>,
) -> String {
    let kind = match variant {
        0 => "invalid input",
        1 => "not found",
        2 => "permission denied",
        3 => "timed out",
        4 => "cancelled",
        5 => "closed",
        6 => "protocol error",
        _ => "I/O error",
    };
    let operation = match operation {
        0 => "read",
        1 => "write",
        2 => "flush",
        3 => "connect",
        4 => "accept",
        5 => "close",
        6 => "resolve",
        _ => "codec",
    };
    let mut text = format!("{kind} during {operation}");
    if let Some(resource) = resource {
        text.push_str(&format!(" `{resource}`"));
    }
    if let Some(cause) = cause {
        text.push_str(&format!(": {cause}"));
    }
    text
}

/// D-TASK-PAUSE-TIER1: one formatter for Task `paused=` / `cancel=` trace text.
/// AOT `JetTask::trace` and the TIR evaluator both call this (I9).
/// D-TASK-PAUSE-TIER1: one formatter for Task `paused=` / `cancel=` trace text.
/// AOT `JetTask::trace` and the TIR evaluator both call this (I9).
pub fn jet_task_control_trace(paused: bool, cancel: bool) -> String {
    format!("paused={paused},cancel={cancel}")
}

