// ── binary.Reader / text.Cursor (D-SHIFT1, c7shift) ──────────────────────────
// The "shift" kernel from linear stream parsing (Jai's `shift` primitive),
// without a dedicated operator (D-SHIFT1=A rejected that). `Reader` owns a
// copy of its byte buffer plus a read position; every read is fallible —
// a bounds miss is an ordinary `Err` string, never a panic or silent
// truncation.
//
// I9: this file is the ONE implementation. `Codegen/mod.rs` splices it verbatim
// into the emitted AOT prelude (`include_str!`), and the canonical TIR
// evaluator calls the same functions directly (`eval/handles.rs`), so quick-run
// and full build read the same bytes and produce the same error text.
// It must stay std-only and free of `crate::` paths: the AOT copy compiles at
// the root of a generated program, not inside this crate.
#[derive(Clone)]
pub struct JetReader {
    pub buf: Vec<u8>,
    pub pos: usize,
}
#[derive(Clone)]
pub struct JetCursor {
    pub buf: String,
    pub pos: usize,
}

pub fn jet_reader_over(bytes: &Vec<u8>) -> JetReader {
    JetReader {
        buf: bytes.clone(),
        pos: 0,
    }
}

pub fn jet_reader_bounds_error(method: &str, need: usize, r: &JetReader) -> String {
    format!(
        "Reader.{}: needed {} byte{} at position {}, only {} remain",
        method,
        need,
        if need == 1 { "" } else { "s" },
        r.pos,
        r.buf.len().saturating_sub(r.pos),
    )
}

pub fn jet_reader_take_fixed(r: &mut JetReader, n: usize, method: &str) -> Result<Vec<u8>, String> {
    if r.pos + n > r.buf.len() {
        return Err(jet_reader_bounds_error(method, n, r));
    }
    let out = r.buf[r.pos..r.pos + n].to_vec();
    r.pos += n;
    Ok(out)
}

pub fn jet_reader_read_u8(r: &mut JetReader) -> Result<u8, String> {
    jet_reader_take_fixed(r, 1, "read_u8").map(|b| b[0])
}
pub fn jet_reader_read_u16_le(r: &mut JetReader) -> Result<u16, String> {
    jet_reader_take_fixed(r, 2, "read_u16_le").map(|b| u16::from_le_bytes([b[0], b[1]]))
}
pub fn jet_reader_read_u16_be(r: &mut JetReader) -> Result<u16, String> {
    jet_reader_take_fixed(r, 2, "read_u16_be").map(|b| u16::from_be_bytes([b[0], b[1]]))
}
pub fn jet_reader_read_u32_le(r: &mut JetReader) -> Result<u32, String> {
    jet_reader_take_fixed(r, 4, "read_u32_le").map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
}
pub fn jet_reader_read_u32_be(r: &mut JetReader) -> Result<u32, String> {
    jet_reader_take_fixed(r, 4, "read_u32_be").map(|b| u32::from_be_bytes([b[0], b[1], b[2], b[3]]))
}
pub fn jet_reader_read_u64_le(r: &mut JetReader) -> Result<u64, String> {
    jet_reader_take_fixed(r, 8, "read_u64_le")
        .map(|b| u64::from_le_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]]))
}
pub fn jet_reader_read_u64_be(r: &mut JetReader) -> Result<u64, String> {
    jet_reader_take_fixed(r, 8, "read_u64_be")
        .map(|b| u64::from_be_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]]))
}

pub fn jet_reader_take(r: &mut JetReader, n: i64) -> Result<Vec<u8>, String> {
    if n < 0 {
        return Err(format!(
            "Reader.take: length must not be negative, got {}",
            n
        ));
    }
    jet_reader_take_fixed(r, n as usize, "take")
}

pub fn jet_reader_remaining(r: &JetReader) -> i64 {
    (r.buf.len() - r.pos) as i64
}

pub fn jet_reader_at_end(r: &JetReader) -> bool {
    r.pos >= r.buf.len()
}

pub fn jet_cursor_over(s: &String) -> JetCursor {
    JetCursor {
        buf: s.clone(),
        pos: 0,
    }
}

pub fn jet_cursor_take_until(c: &mut JetCursor, delim: &String) -> Result<String, String> {
    let tail = &c.buf[c.pos..];
    match tail.find(delim.as_str()) {
        Some(i) => {
            let out = tail[..i].to_string();
            c.pos += i;
            Ok(out)
        }
        None => Err(format!(
            "Cursor.take_until: {:?} not found in the remaining text",
            delim
        )),
    }
}

pub fn jet_cursor_skip_ws(c: &mut JetCursor) {
    let tail = jet_cursor_tail(c);
    let skipped = tail.len() - tail.trim_start().len();
    c.pos += skipped;
}

// `take_pattern` runs a different match engine on every tier: AOT inlines a
// closure specialized to the pattern, the Cranelift host and the interpreter
// walk the pattern as data. What surrounds the match is the same everywhere,
// so it lives here: what the scan may look at, how far a hit advances, and
// what a miss reports. A tier supplies the match and projects the bindings;
// it decides nothing else.

pub fn jet_cursor_tail(c: &JetCursor) -> &str {
    &c.buf[c.pos..]
}

pub fn jet_reader_tail(r: &JetReader) -> &[u8] {
    &r.buf[r.pos..]
}

/// A matched prefix is consumed. `consumed` counts bytes from the tail.
pub fn jet_cursor_take_pattern(c: &mut JetCursor, consumed: usize) {
    c.pos += consumed;
}

pub fn jet_reader_take_pattern(r: &mut JetReader, consumed: usize) {
    r.pos += consumed;
}

/// A miss leaves the position untouched and names it, so a caller can see
/// where the parse stalled.
pub fn jet_cursor_pattern_miss(c: &JetCursor) -> String {
    format!("pattern did not match at cursor position {}", c.pos)
}

pub fn jet_reader_pattern_miss(r: &JetReader) -> String {
    format!("pattern did not match at reader position {}", r.pos)
}

#[cfg(test)]
mod stream_cursor_tests {
    use super::*;

    #[test]
    fn reads_advance_and_report_bounds() {
        let mut r = jet_reader_over(&vec![42, 0, 0, 0, 3, 0, 16, 32, 48]);
        assert_eq!(jet_reader_read_u32_le(&mut r), Ok(42));
        assert_eq!(jet_reader_read_u16_le(&mut r), Ok(3));
        assert_eq!(jet_reader_take(&mut r, 3), Ok(vec![16, 32, 48]));
        assert!(jet_reader_at_end(&r));
        assert_eq!(jet_reader_remaining(&r), 0);
        assert_eq!(
            jet_reader_read_u8(&mut r),
            Err("Reader.read_u8: needed 1 byte at position 9, only 0 remain".to_string())
        );
        assert_eq!(
            jet_reader_take(&mut r, -1),
            Err("Reader.take: length must not be negative, got -1".to_string())
        );
    }

    #[test]
    fn take_pattern_advances_on_a_hit_and_names_the_position_on_a_miss() {
        let mut c = jet_cursor_over(&"abcdef".to_string());
        assert_eq!(jet_cursor_tail(&c), "abcdef");
        jet_cursor_take_pattern(&mut c, 3);
        assert_eq!(jet_cursor_tail(&c), "def");
        assert_eq!(
            jet_cursor_pattern_miss(&c),
            "pattern did not match at cursor position 3"
        );

        let mut r = jet_reader_over(&vec![1, 2, 3, 4]);
        jet_reader_take_pattern(&mut r, 2);
        assert_eq!(jet_reader_tail(&r), &[3, 4]);
        assert_eq!(
            jet_reader_pattern_miss(&r),
            "pattern did not match at reader position 2"
        );
    }

    #[test]
    fn cursor_skips_space_and_takes_until() {
        let mut c = jet_cursor_over(&"   ab|cd".to_string());
        jet_cursor_skip_ws(&mut c);
        assert_eq!(c.pos, 3);
        assert_eq!(
            jet_cursor_take_until(&mut c, &"|".to_string()),
            Ok("ab".to_string())
        );
        assert!(jet_cursor_take_until(&mut c, &"!".to_string()).is_err());
    }
}
// D-BINPAT1 / I9: one binary-pattern scan kernel. `Codegen/mod.rs` embeds this
// exact source in generated AOT programs; Foundation's AST adapter, Cranelift,
// and the TIR evaluator marshal into it. Keep this fragment std-only and free
// of `crate::` paths so it also compiles at the root of generated Rust.

#[derive(Clone, Copy, Debug)]
pub enum JetBinMatchPart<'a> {
    Lit(&'a [u8]),
    Bits { width: usize, little: bool },
    Rest,
}

#[derive(Clone, Debug, PartialEq)]
pub enum JetBinMatchValue {
    Int(u64),
    Rest(Vec<u8>),
}

/// Scan one byte-pattern description from the current bit position.
///
/// `consume_prefix` permits trailing subject bytes, but still requires the
/// match to end on a byte boundary because `Reader` advances by bytes.
pub fn jet_bin_match_scan(
    subject: &[u8],
    parts: &[JetBinMatchPart<'_>],
    consume_prefix: bool,
) -> Option<(usize, Vec<JetBinMatchValue>)> {
    let total = subject.len().checked_mul(8)?;
    let mut bit_pos = 0usize;
    let mut values = Vec::new();

    for part in parts {
        match *part {
            JetBinMatchPart::Lit(bytes) => {
                if bit_pos % 8 != 0 {
                    return None;
                }
                let byte_pos = bit_pos / 8;
                let end = byte_pos.checked_add(bytes.len())?;
                if end > subject.len() || &subject[byte_pos..end] != bytes {
                    return None;
                }
                bit_pos = bit_pos.checked_add(bytes.len().checked_mul(8)?)?;
            }
            JetBinMatchPart::Bits { width, little } => {
                let end = bit_pos.checked_add(width)?;
                if end > total {
                    return None;
                }
                let mut value = 0u64;
                for offset in 0..width {
                    let position = bit_pos + offset;
                    let byte = subject[position / 8];
                    let bit = 7 - (position % 8);
                    value = (value << 1) | u64::from((byte >> bit) & 1);
                }
                if little && width % 8 == 0 {
                    let bytes = width / 8;
                    let mut swapped = 0u64;
                    for index in 0..bytes {
                        swapped |= ((value >> (8 * index)) & 0xff) << (8 * (bytes - 1 - index));
                    }
                    value = swapped;
                }
                bit_pos = end;
                values.push(JetBinMatchValue::Int(value));
            }
            JetBinMatchPart::Rest => {
                if bit_pos % 8 != 0 {
                    return None;
                }
                values.push(JetBinMatchValue::Rest(subject[bit_pos / 8..].to_vec()));
                bit_pos = total;
            }
        }
    }

    if !consume_prefix && bit_pos != total {
        let has_rest = parts
            .iter()
            .any(|part| matches!(*part, JetBinMatchPart::Rest));
        if !has_rest {
            return None;
        }
    }
    if consume_prefix && bit_pos % 8 != 0 {
        return None;
    }
    Some((bit_pos, values))
}
// D-ENV-MUTATE1=A: every generated executable snapshots the host environment
// before user code. Accessors live in the opt-in Core prelude; this mandatory
// foundation is emitted with every entrypoint, including test harnesses.
type JetEnvEntries = Vec<(std::ffi::OsString, std::ffi::OsString)>;

fn jet_env_table() -> &'static std::sync::RwLock<JetEnvEntries> {
    static TABLE: std::sync::OnceLock<std::sync::RwLock<JetEnvEntries>> =
        std::sync::OnceLock::new();
    TABLE.get_or_init(|| {
        let mut entries: JetEnvEntries = Vec::new();
        for (name, value) in std::env::vars_os() {
            if let Some(old) = entries
                .iter()
                .position(|(candidate, _)| jet_env_key_eq(candidate.as_os_str(), name.as_os_str()))
            {
                entries.remove(old);
            }
            entries.push((name, value));
        }
        std::sync::RwLock::new(entries)
    })
}

fn jet_std_env_init() {
    jet_ffi_install_reporter();
    let _ = jet_env_table();
    jet_observe_runtime_start();
}

fn jet_env_read() -> std::sync::RwLockReadGuard<'static, JetEnvEntries> {
    jet_env_table().read().unwrap_or_else(|poisoned| poisoned.into_inner())
}

fn jet_env_write() -> std::sync::RwLockWriteGuard<'static, JetEnvEntries> {
    jet_env_table().write().unwrap_or_else(|poisoned| poisoned.into_inner())
}

#[cfg(unix)]
fn jet_env_key_cmp(left: &std::ffi::OsStr, right: &std::ffi::OsStr) -> std::cmp::Ordering {
    use std::os::unix::ffi::OsStrExt;
    left.as_bytes().cmp(right.as_bytes())
}

// JET_VETTED_UNSAFE_BEGIN: jet_env_windows
#[cfg(windows)]
fn jet_env_key_cmp(left: &std::ffi::OsStr, right: &std::ffi::OsStr) -> std::cmp::Ordering {
    use std::os::windows::ffi::OsStrExt;
    extern "system" {
        fn CompareStringOrdinal(left: *const u16, left_len: i32, right: *const u16, right_len: i32, ignore_case: i32) -> i32;
    }
    let left: Vec<u16> = left.encode_wide().collect();
    let right: Vec<u16> = right.encode_wide().collect();
    let (Ok(left_len), Ok(right_len)) = (i32::try_from(left.len()), i32::try_from(right.len())) else { return left.cmp(&right); };
    let result = unsafe { CompareStringOrdinal(left.as_ptr(), left_len, right.as_ptr(), right_len, 1) };
    match result { 1 => std::cmp::Ordering::Less, 2 => std::cmp::Ordering::Equal, 3 => std::cmp::Ordering::Greater, _ => left.cmp(&right) }
}
// JET_VETTED_UNSAFE_END: jet_env_windows

#[cfg(not(any(unix, windows)))]
fn jet_env_key_cmp(left: &std::ffi::OsStr, right: &std::ffi::OsStr) -> std::cmp::Ordering {
    left.cmp(right)
}

fn jet_env_key_eq(left: &std::ffi::OsStr, right: &std::ffi::OsStr) -> bool {
    jet_env_key_cmp(left, right) == std::cmp::Ordering::Equal
}
mod jet_uninit_semantics {
/// Canonical initialization-state policy for uninitialized storage.
///
/// AOT, web, resident JIT, and TIR evaluation include this exact source. Each
/// engine owns only its value carrier; bounds and readiness live here.
pub fn jet_uninit_bitmap(len: usize) -> Vec<bool> {
    vec![false; len]
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JetUninitAccessError {
    OutOfBounds,
    Uninitialized,
}

pub fn jet_uninit_write(
    bitmap: &mut [bool],
    index: usize,
) -> Result<(usize, bool), JetUninitAccessError> {
    if index >= bitmap.len() {
        return Err(JetUninitAccessError::OutOfBounds);
    }
    let replaced = bitmap[index];
    bitmap[index] = true;
    Ok((index, replaced))
}

pub fn jet_uninit_read(
    bitmap: &[bool],
    index: usize,
) -> Result<usize, JetUninitAccessError> {
    if index >= bitmap.len() {
        return Err(JetUninitAccessError::OutOfBounds);
    }
    if !bitmap[index] {
        return Err(JetUninitAccessError::Uninitialized);
    }
    Ok(index)
}

pub fn jet_uninit_all(bitmap: &[bool]) -> Result<(), JetUninitAccessError> {
    if bitmap.iter().all(|initialized| *initialized) {
        Ok(())
    } else {
        Err(JetUninitAccessError::Uninitialized)
    }
}

/// Safe storage for one value that sema proves is written before use.
/// Invalid scalar bit patterns never exist: `MaybeUninit` stays inside this
/// vetted Prelude module until `write` establishes a real `T`.
pub struct JetUninit<T> {
    value: std::mem::MaybeUninit<T>,
    initialized: bool,
}

impl<T> JetUninit<T> {
    pub fn new() -> Self {
        Self {
            value: std::mem::MaybeUninit::uninit(),
            initialized: false,
        }
    }

    pub fn write(&mut self, value: T) {
        if self.initialized {
            // SAFETY: the flag is set only after a successful write.
            unsafe { self.value.assume_init_drop() };
        }
        self.value.write(value);
        self.initialized = true;
    }

    pub fn read(&self) -> &T {
        assert!(self.initialized, "value read before initialization");
        // SAFETY: the checked flag proves `write` initialized the value.
        unsafe { self.value.assume_init_ref() }
    }
}

impl<T> Drop for JetUninit<T> {
    fn drop(&mut self) {
        if self.initialized {
            // SAFETY: the checked flag proves `write` initialized the value.
            unsafe { self.value.assume_init_drop() };
        }
    }
}

/// Safe storage for a fixed list whose elements are filled before use.
/// The payload bytes are not zeroed. The initialized bitmap makes the safe
/// indexing API sound even if a compiler regression misses the sema proof.
pub struct JetUninitFixed<T, const N: usize> {
    values: [std::mem::MaybeUninit<T>; N],
    initialized: [bool; N],
}

impl<T, const N: usize> JetUninitFixed<T, N> {
    pub fn new() -> Self {
        Self {
            values: std::array::from_fn(|_| std::mem::MaybeUninit::uninit()),
            initialized: [false; N],
        }
    }

    pub fn len(&self) -> usize {
        N
    }

    pub fn write(&mut self, index: usize, value: T) {
        let (index, replaced) = jet_uninit_write(&mut self.initialized, index)
            .expect("fixed-list index out of range");
        if replaced {
            // SAFETY: the bitmap is set only after `write` initializes this slot.
            unsafe { self.values[index].assume_init_drop() };
        }
        self.values[index].write(value);
        self.initialized[index] = true;
    }

    pub fn write_array(&mut self, values: [T; N]) {
        for (index, value) in values.into_iter().enumerate() {
            self.write(index, value);
        }
    }

    pub fn read_array(&self) -> [T; N]
    where
        T: Clone,
    {
        jet_uninit_all(&self.initialized)
            .expect("fixed list read before every element was initialized");
        std::array::from_fn(|index| self[index].clone())
    }

    pub fn as_array(&self) -> &[T; N] {
        jet_uninit_all(&self.initialized)
            .expect("fixed list read before every element was initialized");
        // SAFETY: every slot is initialized and `[MaybeUninit<T>; N]` has the
        // same layout as `[T; N]`.
        unsafe { &*((&self.values as *const [std::mem::MaybeUninit<T>; N]).cast::<[T; N]>()) }
    }

    pub fn as_array_mut(&mut self) -> &mut [T; N] {
        jet_uninit_all(&self.initialized)
            .expect("fixed list read before every element was initialized");
        // SAFETY: every slot is initialized and the exclusive borrow prevents
        // aliasing while the ordinary fixed-list view is live.
        unsafe {
            &mut *((&mut self.values as *mut [std::mem::MaybeUninit<T>; N]).cast::<[T; N]>())
        }
    }

    pub fn uninit_bytes(&mut self) -> &mut [std::mem::MaybeUninit<T>] {
        &mut self.values
    }
}

impl<T, const N: usize> std::ops::Index<usize> for JetUninitFixed<T, N> {
    type Output = T;

    fn index(&self, index: usize) -> &Self::Output {
        let index =
            jet_uninit_read(&self.initialized, index).expect("fixed-list element is not readable");
        // SAFETY: the canonical readiness check proves this slot was initialized.
        unsafe { self.values[index].assume_init_ref() }
    }
}

impl<T, const N: usize> Drop for JetUninitFixed<T, N> {
    fn drop(&mut self) {
        for index in 0..N {
            if self.initialized[index] {
                // SAFETY: the checked bitmap proves this slot was initialized.
                unsafe { self.values[index].assume_init_drop() };
            }
        }
    }
}

}
