pub trait __jet_Close {
    fn close(self);
}

struct JetResource<T: __jet_Close>(Option<T>);
impl<T: __jet_Close> JetResource<T> { fn new(value: T) -> Self { Self(Some(value)) } fn take(&mut self) -> T { self.0.take().expect("resource already consumed") } fn close(&mut self) { if let Some(value) = self.0.take() { __jet_Close::close(value); } } }
impl<T: __jet_Close> std::ops::Deref for JetResource<T> { type Target = T; fn deref(&self) -> &T { self.0.as_ref().expect("resource already consumed") } }
impl<T: __jet_Close> std::ops::DerefMut for JetResource<T> { fn deref_mut(&mut self) -> &mut T { self.0.as_mut().expect("resource already consumed") } }
impl<T: __jet_Close> Drop for JetResource<T> { fn drop(&mut self) { self.close(); } }



pub fn __jet_run() -> JetOutcome<(), JetErr> {
    let __jet_stack_frame = crate::jet_stack_enter("hello.jet", 2, "run", "fn run() { print(\"hello, world\") }");
    { let _ = jet_term_write_stdout_line(&(("hello, world".to_string()).jet_show()), false); };
    Ok(())
}


fn main() {
    jet_std_env_init();
    jet_mem::jet_sentry_set_hardened(false);
    jet_gc::runtime_or_exit(jet_gc::initialize_trace());
    jet_runtime_boundary(|| {
        if let Err(__jet___entry_error) = __jet_run() {
            jet_entry_error_exit(jet_entry_error_text(&__jet___entry_error));
        }
    });
}

